{
  "name": "metro-rush",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "description": "Metro Rush — a three-lane 3D endless runner",
  "scripts": {
    "dev": "vite --host 0.0.0.0",
    "build": "vite build --base ./",
    "preview": "vite preview --host 0.0.0.0"
  },
  "dependencies": {
    "three": "0.187.0"
  },
  "devDependencies": {
    "vite": "8.3.5"
  }
}

@font-face {
  font-family: "Bungee";
  src: url("./fonts/bungee.ttf") format("truetype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Space Grotesk";
  src: url("./fonts/space-grotesk-regular.ttf") format("truetype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Space Grotesk";
  src: url("./fonts/space-grotesk-semibold.ttf") format("truetype");
  font-weight: 600;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Space Grotesk";
  src: url("./fonts/space-grotesk-bold.ttf") format("truetype");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

:root {
  --ink: #101c31;
  --ink-soft: #1b2a45;
  --cream: #fff4e3;
  --cream-dim: rgba(255, 244, 227, 0.66);
  --orange: #ff6738;
  --orange-deep: #e7471d;
  --gold: #ffc83d;
  --mint: #7ce3c4;
  --glass: rgba(12, 24, 43, 0.76);
  --line: rgba(255, 244, 227, 0.16);
  --display: "Bungee", "Arial Black", sans-serif;
  --body: "Space Grotesk", "Trebuchet MS", sans-serif;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #f4b28a;
  color: var(--cream);
  font-family: var(--body);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  padding: 0;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

[hidden] {
  display: none !important;
}

#app {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 100svh;
  overflow: hidden;
  isolation: isolate;
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  touch-action: none;
}

.scene-wash {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(255, 166, 115, 0.06), transparent 28%),
    linear-gradient(0deg, rgba(11, 19, 34, 0.26), transparent 34%);
  mix-blend-mode: multiply;
}

.vignette {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background: radial-gradient(ellipse at 50% 42%, transparent 40%, rgba(8, 15, 29, 0.34) 100%);
}

.grain {
  position: absolute;
  inset: -30%;
  z-index: 3;
  opacity: 0.06;
  pointer-events: none;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.95' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.55'/%3E%3C/svg%3E");
  animation: grain-shift 0.6s steps(2) infinite;
}

@keyframes grain-shift {
  0% { transform: translate(0, 0); }
  25% { transform: translate(2%, -1%); }
  50% { transform: translate(-1%, 2%); }
  75% { transform: translate(1%, 1%); }
  100% { transform: translate(-2%, -1%); }
}

.eyebrow {
  display: block;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.18em;
  line-height: 1;
  color: rgba(255, 244, 227, 0.58);
}

/* ————————————————————————————— HUD ————————————————————————————— */

#hud {
  position: absolute;
  z-index: 12;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: calc(20px + var(--safe-top)) 28px 0;
  pointer-events: none;
  animation: hud-in 0.55s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes hud-in {
  from { opacity: 0; transform: translateY(-16px); }
  to { opacity: 1; transform: translateY(0); }
}

.hud-left,
.hud-right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-mark {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: var(--orange);
  color: var(--ink);
  box-shadow: 0 10px 26px rgba(61, 25, 14, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.28);
}

.brand-mark svg {
  width: 30px;
  height: 30px;
}

.score-block {
  min-width: 150px;
  padding: 8px 18px 7px;
  border-radius: 12px;
  background: linear-gradient(135deg, rgba(13, 25, 44, 0.86), rgba(13, 25, 44, 0.58));
  border: 1px solid rgba(255, 244, 227, 0.12);
  box-shadow: 0 12px 32px rgba(4, 10, 20, 0.22);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.score-value {
  display: block;
  font-family: var(--display);
  font-size: 27px;
  letter-spacing: 0.035em;
  line-height: 1.18;
  color: var(--cream);
  font-variant-numeric: tabular-nums;
  transition: transform 0.18s ease, color 0.18s ease;
}

.score-value.bump {
  transform: scale(1.06);
  color: var(--gold);
}

.distance-block {
  padding: 0 4px;
}

.distance-block .eyebrow {
  margin-bottom: 6px;
}

.distance-value {
  display: flex;
  align-items: baseline;
  gap: 2px;
  font-weight: 700;
  font-size: 17px;
  color: rgba(255, 244, 227, 0.9);
  font-variant-numeric: tabular-nums;
  text-shadow: 0 2px 10px rgba(4, 10, 20, 0.4);
}

.distance-value small {
  font-size: 9px;
  opacity: 0.55;
}

.speed-pill {
  width: 150px;
  margin-top: 9px;
  padding: 9px 13px 11px;
  border-radius: 13px;
  background: rgba(12, 24, 43, 0.54);
  border: 1px solid rgba(255, 244, 227, 0.12);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 12px 32px rgba(4, 10, 20, 0.16);
}

.speed-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: rgba(255, 244, 227, 0.54);
}

.speed-label b {
  color: var(--gold);
  font-size: 11px;
  letter-spacing: 0.02em;
}

.speed-bar {
  width: 100%;
  height: 3px;
  overflow: hidden;
  border-radius: 9px;
  background: rgba(255, 244, 227, 0.16);
}

.speed-bar i {
  display: block;
  width: 0%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--mint), var(--gold), var(--orange));
  box-shadow: 0 0 9px rgba(255, 200, 61, 0.5);
  transition: width 0.2s linear;
}

.hud-right {
  margin-top: 5px;
}

.coin-pill {
  display: flex;
  align-items: center;
  gap: 9px;
  height: 40px;
  padding: 0 15px 0 11px;
  border-radius: 999px;
  background: rgba(12, 24, 43, 0.68);
  border: 1px solid rgba(255, 200, 61, 0.24);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 10px 26px rgba(4, 10, 20, 0.18);
}

.coin-icon {
  position: relative;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: radial-gradient(circle at 36% 30%, #fff6b8 0 12%, #ffd84d 13% 52%, #e8a318 53% 100%);
  box-shadow: inset 0 0 0 2px rgba(141, 90, 0, 0.3), 0 0 12px rgba(255, 200, 61, 0.28);
}

.coin-icon::after {
  content: "";
  position: absolute;
  inset: 6px;
  border-radius: 50%;
  border: 1px solid rgba(128, 78, 0, 0.34);
}

.coin-pill b {
  font-family: var(--display);
  font-size: 16px;
  color: var(--cream);
  font-variant-numeric: tabular-nums;
}

.best-pill {
  height: 40px;
  padding: 7px 14px;
  border-radius: 12px;
  background: rgba(12, 24, 43, 0.4);
  border: 1px solid rgba(255, 244, 227, 0.1);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.best-pill .eyebrow {
  margin-bottom: 4px;
}

.best-pill b {
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
}

.icon-button {
  pointer-events: auto;
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: rgba(255, 244, 227, 0.88);
  background: rgba(12, 24, 43, 0.46);
  border: 1px solid rgba(255, 244, 227, 0.12);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  transition: background 0.18s ease, transform 0.18s ease;
}

.icon-button:hover {
  background: rgba(255, 103, 56, 0.88);
  transform: translateY(-1px);
}

.icon-button:active {
  transform: scale(0.94);
}

.icon-button svg {
  width: 20px;
  height: 20px;
}

.sound-off {
  display: none;
}

#soundButton.muted .sound-on {
  display: none;
}

#soundButton.muted .sound-off {
  display: block;
}

.lane-meter {
  position: absolute;
  z-index: 11;
  left: 50%;
  bottom: calc(26px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 8px 14px;
  border-radius: 999px;
  background: rgba(11, 22, 39, 0.5);
  border: 1px solid rgba(255, 244, 227, 0.1);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  pointer-events: none;
}

.lane-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: rgba(255, 244, 227, 0.5);
}

.lane-dots {
  display: flex;
  gap: 5px;
}

.lane-dots i {
  width: 22px;
  height: 4px;
  border-radius: 6px;
  background: rgba(255, 244, 227, 0.22);
  transition: width 0.2s ease, background 0.2s ease;
}

.lane-dots i.active {
  width: 32px;
  background: var(--orange);
  box-shadow: 0 0 12px rgba(255, 103, 56, 0.55);
}

.power-up {
  position: absolute;
  z-index: 12;
  left: 50%;
  top: calc(88px + var(--safe-top));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 17px 8px 8px;
  border-radius: 999px;
  background: rgba(18, 42, 58, 0.84);
  border: 1px solid rgba(124, 227, 196, 0.42);
  box-shadow: 0 0 28px rgba(124, 227, 196, 0.18);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  animation: pop-in 0.35s cubic-bezier(0.2, 1.4, 0.4, 1) both;
}

.power-icon {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--mint);
  color: #123a32;
  font-size: 16px;
}

.power-up div {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.power-up b {
  font-size: 10px;
  letter-spacing: 0.14em;
}

.power-up small {
  font-size: 10px;
  color: var(--mint);
  font-weight: 700;
}

.toast {
  position: absolute;
  z-index: 13;
  left: 50%;
  top: 23%;
  transform: translate(-50%, 8px);
  padding: 9px 18px;
  border-radius: 999px;
  background: rgba(12, 24, 43, 0.74);
  border: 1px solid rgba(255, 244, 227, 0.16);
  color: var(--cream);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.18em;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease, transform 0.2s ease;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  white-space: nowrap;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ————————————————————————————— START ————————————————————————————— */

.screen {
  position: absolute;
  inset: 0;
  z-index: 20;
}

.start-screen {
  display: grid;
  grid-template-columns: minmax(440px, 1.1fr) minmax(250px, 0.9fr);
  padding: clamp(28px, 5vw, 76px) clamp(24px, 6vw, 96px) calc(64px + var(--safe-bottom));
  background:
    linear-gradient(90deg, rgba(9, 19, 35, 0.94) 0%, rgba(9, 19, 35, 0.82) 31%, rgba(9, 19, 35, 0.32) 58%, rgba(9, 19, 35, 0.06) 78%),
    linear-gradient(0deg, rgba(9, 19, 35, 0.72) 0%, transparent 26%),
    linear-gradient(180deg, rgba(9, 19, 35, 0.28), transparent 18%);
  transition: opacity 0.45s ease, visibility 0.45s;
}

.start-screen.is-leaving {
  opacity: 0;
  visibility: hidden;
}

.intro-copy {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  position: relative;
  z-index: 2;
  max-width: 640px;
  padding-bottom: 4vh;
}

.kicker {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.24em;
  color: rgba(255, 244, 227, 0.66);
  animation: rise-in 0.7s 0.05s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.kicker > span {
  width: 22px;
  height: 1px;
  background: var(--orange);
  box-shadow: 0 0 8px rgba(255, 103, 56, 0.6);
}

.kicker.danger {
  color: var(--orange);
}

.logo {
  margin: 18px 0 22px;
  font-family: var(--display);
  font-size: clamp(78px, 10.4vw, 152px);
  line-height: 0.79;
  letter-spacing: -0.015em;
  transform: rotate(-2deg);
  transform-origin: left center;
  filter: drop-shadow(0 22px 36px rgba(3, 9, 19, 0.38));
}

.logo span {
  display: block;
  animation: logo-in 0.8s cubic-bezier(0.18, 1, 0.22, 1) both;
}

.logo-top {
  color: var(--cream);
  -webkit-text-stroke: 2px rgba(255, 244, 227, 0.3);
  text-shadow: 0 4px 0 rgba(16, 28, 49, 0.28);
}

.logo-bottom {
  color: var(--orange);
  margin-left: 0.1em;
  animation-delay: 0.08s !important;
  text-shadow: 0 5px 0 rgba(136, 42, 11, 0.32);
}

.logo-dot {
  display: inline !important;
  color: var(--gold);
  text-shadow: none;
  animation: none !important;
}

@keyframes logo-in {
  from { opacity: 0; transform: translateX(-44px) skewX(-5deg); }
  to { opacity: 1; transform: translateX(0) skewX(0); }
}

@keyframes rise-in {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

.tagline {
  margin: 0 0 32px;
  max-width: 490px;
  font-size: clamp(14px, 1.25vw, 17px);
  line-height: 1.6;
  color: rgba(255, 244, 227, 0.72);
  animation: rise-in 0.7s 0.18s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.start-actions {
  display: flex;
  align-items: center;
  gap: 28px;
  animation: rise-in 0.7s 0.26s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.play-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  min-width: 208px;
  height: 64px;
  padding: 0 17px 0 27px;
  overflow: hidden;
  border-radius: 12px;
  background: var(--orange);
  color: #fff9ef;
  font-family: var(--display);
  font-size: 17px;
  letter-spacing: 0.03em;
  box-shadow: 0 16px 34px rgba(105, 31, 9, 0.34), inset 0 1px 0 rgba(255, 255, 255, 0.25);
  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
  pointer-events: auto;
}

.play-button::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(112deg, transparent 25%, rgba(255, 255, 255, 0.22) 46%, transparent 66%);
  transform: translateX(-120%);
  transition: transform 0.5s ease;
}

.play-button:hover {
  transform: translateY(-2px);
  background: #ff774b;
  box-shadow: 0 22px 42px rgba(105, 31, 9, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.25);
}

.play-button:hover::before {
  transform: translateX(120%);
}

.play-button:active {
  transform: translateY(1px) scale(0.99);
}

.play-arrow {
  width: 35px;
  height: 35px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  background: rgba(16, 28, 49, 0.18);
  font-family: var(--body);
  font-size: 20px;
  line-height: 1;
  transition: transform 0.2s ease;
}

.play-button:hover .play-arrow {
  transform: translateX(3px);
}

.play-button.compact {
  min-width: 190px;
  height: 56px;
  font-size: 14px;
}

.best-badge {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-left: 25px;
  border-left: 1px solid rgba(255, 244, 227, 0.18);
}

.best-badge b {
  font-family: var(--display);
  font-size: 20px;
  color: var(--gold);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.04em;
}

.control-hints {
  display: flex;
  align-items: center;
  gap: clamp(16px, 2.5vw, 34px);
  margin-top: clamp(30px, 6vh, 62px);
  animation: rise-in 0.7s 0.36s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.hint {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.hint > span:last-child {
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255, 244, 227, 0.46);
}

.keys {
  display: flex;
  align-items: center;
  gap: 4px;
  min-height: 22px;
}

kbd {
  display: inline-grid;
  place-items: center;
  min-width: 23px;
  height: 22px;
  padding: 0 6px;
  border-radius: 5px;
  border: 1px solid rgba(255, 244, 227, 0.23);
  background: rgba(255, 244, 227, 0.08);
  box-shadow: 0 2px 0 rgba(0, 0, 0, 0.18);
  font-family: var(--body);
  font-size: 9px;
  font-weight: 700;
  color: rgba(255, 244, 227, 0.74);
}

.touch-hint {
  display: none;
}

.intro-side {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: flex-end;
  padding-bottom: 2vh;
}

.route-card {
  width: 190px;
  padding: 17px;
  border: 1px solid rgba(255, 244, 227, 0.17);
  border-radius: 14px;
  background: rgba(10, 21, 39, 0.3);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  animation: rise-in 0.8s 0.46s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.route-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 18px;
}

.route-head span {
  font-size: 8px;
  letter-spacing: 0.2em;
  color: rgba(255, 244, 227, 0.5);
}

.route-head b {
  font-family: var(--display);
  font-size: 22px;
  line-height: 0.8;
  color: var(--orange);
}

.route-track {
  position: relative;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 13px;
}

.route-track::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 1px;
  background: rgba(255, 244, 227, 0.22);
}

.route-track i {
  position: relative;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--cream);
  box-shadow: 0 0 0 3px rgba(10, 21, 39, 0.6);
}

.route-track i:last-of-type {
  background: var(--orange);
}

.route-runner {
  position: absolute;
  left: 42%;
  top: 4px;
  width: 7px;
  height: 36px;
  border-radius: 8px;
  background: var(--gold);
  box-shadow: 0 0 14px rgba(255, 200, 61, 0.55);
  animation: route-pulse 2.2s ease-in-out infinite;
}

@keyframes route-pulse {
  0%, 100% { transform: translateY(0); opacity: 0.9; }
  50% { transform: translateY(-5px); opacity: 1; }
}

.route-note {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.17em;
  color: rgba(255, 244, 227, 0.42);
}

.scroll-note {
  position: absolute;
  right: 2px;
  bottom: 12%;
  display: flex;
  align-items: center;
  gap: 9px;
  writing-mode: vertical-rl;
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.22em;
  color: rgba(255, 244, 227, 0.28);
}

.scroll-note span {
  width: 1px;
  height: 38px;
  background: rgba(255, 244, 227, 0.24);
}

.intro-footer {
  position: absolute;
  left: clamp(24px, 6vw, 96px);
  right: clamp(24px, 6vw, 96px);
  bottom: calc(20px + var(--safe-bottom));
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.16em;
  color: rgba(255, 244, 227, 0.32);
  pointer-events: none;
}

.footer-center {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
}

.text-button {
  pointer-events: auto;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.17em;
  color: rgba(255, 244, 227, 0.55);
  border-bottom: 1px solid rgba(255, 244, 227, 0.22);
  padding-bottom: 2px;
  transition: color 0.2s ease, border-color 0.2s ease;
}

.text-button:hover {
  color: var(--orange);
  border-color: var(--orange);
}

/* ————————————————————————————— MODALS ————————————————————————————— */

.modal-screen {
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(ellipse at 50% 40%, rgba(10, 21, 38, 0.44), rgba(6, 13, 25, 0.82)),
    rgba(6, 13, 25, 0.25);
  backdrop-filter: blur(7px) saturate(0.8);
  -webkit-backdrop-filter: blur(7px) saturate(0.8);
  animation: fade-in 0.3s ease both;
}

@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

.modal-card {
  position: relative;
  width: min(560px, 100%);
  padding: clamp(28px, 4vw, 48px);
  border-radius: 20px;
  border: 1px solid rgba(255, 244, 227, 0.17);
  background:
    linear-gradient(145deg, rgba(27, 42, 69, 0.96), rgba(11, 22, 39, 0.97)),
    var(--ink);
  box-shadow: 0 40px 100px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.09);
  animation: modal-in 0.45s cubic-bezier(0.18, 1.25, 0.3, 1) both;
}

@keyframes modal-in {
  from { opacity: 0; transform: translateY(24px) scale(0.97); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.modal-card::before {
  content: "";
  position: absolute;
  left: 14%;
  right: 14%;
  top: -1px;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--orange), transparent);
  opacity: 0.85;
}

.modal-card h2 {
  margin: 16px 0 8px;
  font-family: var(--display);
  font-size: clamp(40px, 6vw, 66px);
  line-height: 0.9;
  letter-spacing: -0.01em;
  color: var(--cream);
}

.gameover-card h2 {
  color: var(--orange);
}

.gameover-sub {
  margin: 0 0 27px;
  font-size: 13px;
  line-height: 1.5;
  color: rgba(255, 244, 227, 0.56);
}

.result-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 24px;
  padding: 22px 0;
  margin-bottom: 27px;
  border-top: 1px solid rgba(255, 244, 227, 0.14);
  border-bottom: 1px solid rgba(255, 244, 227, 0.14);
}

.result-main {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.result-main .eyebrow {
  margin-bottom: 7px;
}

.result-main > b {
  font-family: var(--display);
  font-size: clamp(34px, 4.4vw, 48px);
  line-height: 1;
  color: var(--gold);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
}

.result-main em {
  align-self: flex-start;
  margin-top: 10px;
  padding: 4px 7px;
  border-radius: 3px;
  background: var(--mint);
  color: #123a32;
  font-style: normal;
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.14em;
}

.result-side {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.result-side > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.result-side span {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: rgba(255, 244, 227, 0.4);
}

.result-side b {
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  color: rgba(255, 244, 227, 0.92);
}

.modal-actions {
  display: flex;
  align-items: center;
  gap: 14px;
}

.ghost-button {
  height: 56px;
  padding: 0 25px;
  border-radius: 12px;
  border: 1px solid rgba(255, 244, 227, 0.18);
  color: rgba(255, 244, 227, 0.7);
