  font-size: 12px;
  letter-spacing: 0.05em;
  transition: background 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}

.ghost-button:hover {
  background: rgba(255, 244, 227, 0.08);
  border-color: rgba(255, 244, 227, 0.32);
  color: var(--cream);
}

.pause-stats {
  display: flex;
  gap: 32px;
  margin: 5px 0 28px;
  padding: 20px 0;
