  border-bottom: 1px solid rgba(255, 244, 227, 0.14);
}

.pause-stats span {
  display: block;
  margin-bottom: 5px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: rgba(255, 244, 227, 0.42);
}

.pause-stats b {
  font-family: var(--display);
  font-size: 25px;
  color: var(--cream);
