  place-items: center;
  background: rgba(255, 244, 227, 0.07);
  color: rgba(255, 244, 227, 0.65);
  font-size: 22px;
  line-height: 1;
  transition: background 0.2s ease, color 0.2s ease;
}

.close-button:hover {
  background: rgba(255, 103, 56, 0.2);
  color: var(--cream);
}

.how-card {
  width: min(690px, 100%);
}

.how-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px 26px;
  margin: 25px 0 22px;
