/* ————————————————————————————— TOUCH ————————————————————————————— */

.touch-controls {
  position: absolute;
  z-index: 14;
  left: 16px;
  right: 16px;
  bottom: calc(16px + var(--safe-bottom));
  display: flex;
  justify-content: space-between;
  pointer-events: none;
}

.touch-cluster {
  display: flex;
  gap: 9px;
}

.touch-button {
  pointer-events: auto;
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: rgba(255, 244, 227, 0.84);
  background: rgba(10, 22, 40, 0.48);
  border: 1px solid rgba(255, 244, 227, 0.2);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
  touch-action: manipulation;
  user-select: none;
}

.touch-button svg {
  width: 25px;
  height: 25px;
}

.touch-button:active,
.touch-button.pressed {
  background: rgba(255, 103, 56, 0.8);
  transform: scale(0.93);
}

.webgl-fallback {
  position: absolute;
  inset: 0;
  z-index: 50;
  display: grid;
  place-content: center;
  gap: 10px;
  padding: 30px;
  text-align: center;
  background: var(--ink);
}

.webgl-fallback h2 {
  margin: 0;
  font-family: var(--display);
  color: var(--orange);
  font-size: 32px;
}

.webgl-fallback p {
  max-width: 440px;
  margin: 0;
  color: var(--cream-dim);
  line-height: 1.6;
}

