    min-width: 178px;
    font-size: 13px;
  }

  .control-hints {
    margin-top: 14px;
  }

  .lane-meter {
    bottom: calc(18px + var(--safe-bottom));
  }

  .touch-controls {
    bottom: calc(11px + var(--safe-bottom));
  }

  .touch-button {
    width: 45px;
    height: 45px;
  }

  .modal-card {
    max-width: 620px;
    padding: 21px 26px;
  }

  .modal-card h2 {
    font-size: 33px;
    margin-top: 10px;
  }

  .gameover-sub {
    margin-bottom: 13px;
  }

  .result-grid {
    padding: 11px 0;
    margin-bottom: 14px;
