  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

/**
 * Tiny procedural sound engine. Everything is synthesized with Web Audio,
 * so the game stays a single self-contained bundle.
 */
export class SoundEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.muted = false;
    this.musicTimer = 0;
    this.step = 0;
    this.nextNoteTime = 0;
    this.started = false;
    this.musicOn = false;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    const compressor = this.ctx.createDynamicsCompressor();
    compressor.threshold.value = -18;
    compressor.knee.value = 18;
    compressor.ratio.value = 5;
    compressor.attack.value = 0.004;
    compressor.release.value = 0.2;

    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.75;
    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.16;
    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = 0.5;

    this.musicGain.connect(this.master);
    this.sfxGain.connect(this.master);
    this.master.connect(compressor);
    compressor.connect(this.ctx.destination);
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(muted ? 0 : 0.75, this.ctx.currentTime, 0.03);
    }
  }

  toggleMuted() {
    this.setMuted(!this.muted);
    return this.muted;
  }

  startMusic() {
    this.init();
    if (!this.ctx || this.musicOn) return;
    this.musicOn = true;
    this.step = 0;
    this.nextNoteTime = this.ctx.currentTime + 0.08;
    this.musicTimer = window.setInterval(() => this.scheduleMusic(), 55);
  }

  stopMusic() {
    this.musicOn = false;
    window.clearInterval(this.musicTimer);
  }

  scheduleMusic() {
    if (!this.ctx || !this.musicOn) return;
    const stepDur = 60 / 128 / 4;
    while (this.nextNoteTime < this.ctx.currentTime + 0.16) {
      this.playStep(this.step, this.nextNoteTime, stepDur);
      this.step = (this.step + 1) % 64;
      this.nextNoteTime += stepDur;
    }
  }

  playStep(step, time, dur) {
    const bassNotes = [55, 55, 65.41, 49, 55, 55, 73.42, 65.41];
    if (step % 8 === 0) {
      const note = bassNotes[(step / 8) % bassNotes.length];
      this.tone(note, time, dur * 6.4, 'sawtooth', 0.12, this.musicGain, 240);
      this.kick(time);
    }
    if (step % 4 === 2) this.hat(time, 0.03);
    if (step % 2 === 0) {
      const arp = [220, 261.63, 329.63, 392, 329.63, 261.63, 246.94, 293.66];
      const f = arp[(step / 2) % arp.length];
      this.tone(f, time, dur * 2.2, 'triangle', 0.028, this.musicGain, 1200);
    }
    if (step % 16 === 12) this.tone(110, time, dur * 3, 'sine', 0.035, this.musicGain, 600);
  }

  kick(time) {
    if (!this.ctx) return;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.frequency.setValueAtTime(130, time);
    osc.frequency.exponentialRampToValueAtTime(42, time + 0.12);
    gain.gain.setValueAtTime(0.26, time);
    gain.gain.exponentialRampToValueAtTime(0.001, time + 0.17);
    osc.connect(gain).connect(this.musicGain);
    osc.start(time);
    osc.stop(time + 0.18);
  }

  hat(time, volume) {
    if (!this.ctx) return;
    const buffer = this.noiseBuffer(0.05);
    const source = this.ctx.createBufferSource();
    const filter = this.ctx.createBiquadFilter();
    const gain = this.ctx.createGain();
    source.buffer = buffer;
    filter.type = 'highpass';
    filter.frequency.value = 7000;
    gain.gain.value = volume;
    source.connect(filter).connect(gain).connect(this.musicGain);
    source.start(time);
  }

  noiseBuffer(seconds) {
    const length = Math.floor(this.ctx.sampleRate * seconds);
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1;
    return buffer;
  }

  tone(freq, time, duration, type, volume, destination, lowpass = 0) {
    if (!this.ctx) return;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, time);
    gain.gain.setValueAtTime(0.0001, time);
    gain.gain.exponentialRampToValueAtTime(volume, time + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, time + duration);
    let tail = gain;
    if (lowpass) {
      const filter = this.ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = lowpass;
      gain.connect(filter);
      tail = filter;
    }
    osc.connect(gain);
    tail.connect(destination || this.sfxGain);
    osc.start(time);
    osc.stop(time + duration + 0.02);
  }

  coin(streak = 0) {
    this.init();
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const base = 880 * Math.pow(2, Math.min(streak, 8) / 24);
    this.tone(base, t, 0.08, 'sine', 0.15, this.sfxGain, 4500);
    this.tone(base * 1.5, t + 0.055, 0.12, 'sine', 0.1, this.sfxGain, 5000);
  }

  jump() {
    this.init();
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const source = this.ctx.createBufferSource();
    source.buffer = this.noiseBuffer(0.18);
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(500, t);
    filter.frequency.exponentialRampToValueAtTime(1800, t + 0.14);
    filter.Q.value = 1.2;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(0.09, t + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.18);
    source.connect(filter).connect(gain).connect(this.sfxGain);
    source.start(t);
  }

  swipe(direction = 0) {
    this.init();
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(direction > 0 ? 240 : 330, t);
    osc.frequency.exponentialRampToValueAtTime(direction > 0 ? 390 : 180, t + 0.1);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(0.07, t + 0.015);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.13);
    osc.connect(gain).connect(this.sfxGain);
    osc.start(t);
    osc.stop(t + 0.15);
  }

  slide() {
    this.init();
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const source = this.ctx.createBufferSource();
    source.buffer = this.noiseBuffer(0.32);
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(1400, t);
    filter.frequency.exponentialRampToValueAtTime(260, t + 0.28);
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.09, t);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.3);
    source.connect(filter).connect(gain).connect(this.sfxGain);
    source.start(t);
  }

  power() {
    this.init();
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    [523, 659, 784, 1047].forEach((f, i) => this.tone(f, t + i * 0.055, 0.22, 'triangle', 0.08, this.sfxGain, 4000));
  }

  crash() {
    this.init();
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const source = this.ctx.createBufferSource();
    source.buffer = this.noiseBuffer(0.8);
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(1300, t);
    filter.frequency.exponentialRampToValueAtTime(120, t + 0.65);
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.5, t);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.7);
    source.connect(filter).connect(gain).connect(this.sfxGain);
    source.start(t);
    const osc = this.ctx.createOscillator();
    const g2 = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(120, t);
    osc.frequency.exponentialRampToValueAtTime(34, t + 0.55);
    g2.gain.setValueAtTime(0.4, t);
    g2.gain.exponentialRampToValueAtTime(0.0001, t + 0.65);
    osc.connect(g2).connect(this.sfxGain);
    osc.start(t);
    osc.stop(t + 0.7);
  }

  click() {
    this.init();
    if (!this.ctx) return;
    this.tone(520, this.ctx.currentTime, 0.05, 'sine', 0.045, this.sfxGain, 2200);
  }
}

import * as THREE from "three";

export const LANE_X = [-2.4, 0, 2.4];
export const TRACK_AHEAD = 300;

const rand = (min, max) => min + Math.random() * (max - min);
const pick = (list) => list[Math.floor(Math.random() * list.length)];

function canvasTexture(width, height, draw) {
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext("2d");
  draw(ctx, width, height);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.anisotropy = 4;
  return texture;
}

function makeBallastTexture() {
  const texture = canvasTexture(512, 512, (ctx, w, h) => {
    ctx.fillStyle = "#34343a";
    ctx.fillRect(0, 0, w, h);
    const shades = ["#292a2f", "#414147", "#4d4b4d", "#24252a", "#595552", "#3b3c42"];
    for (let i = 0; i < 7000; i++) {
      ctx.fillStyle = pick(shades);
      const x = Math.random() * w;
      const y = Math.random() * h;
      const size = Math.random() * 4 + 0.8;
      ctx.beginPath();
      ctx.ellipse(x, y, size, size * 0.7, Math.random() * Math.PI, 0, Math.PI * 2);
      ctx.fill();
    }
    const grad = ctx.createLinearGradient(0, 0, w, 0);
    grad.addColorStop(0, "rgba(0,0,0,.18)");
    grad.addColorStop(0.2, "rgba(255,255,255,.03)");
    grad.addColorStop(0.5, "rgba(255,255,255,.06)");
    grad.addColorStop(0.8, "rgba(255,255,255,.03)");
    grad.addColorStop(1, "rgba(0,0,0,.18)");
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
  });
  texture.repeat.set(1.2, 56);
  return texture;
}

function makeConcreteTexture() {
  const texture = canvasTexture(256, 256, (ctx, w, h) => {
    ctx.fillStyle = "#9a8d80";
    ctx.fillRect(0, 0, w, h);
    for (let i = 0; i < 900; i++) {
      ctx.fillStyle = `rgba(${rand(50, 110) | 0},${rand(50, 100) | 0},${rand(50, 95) | 0},${rand(0.03, 0.13)})`;
      ctx.fillRect(Math.random() * w, Math.random() * h, rand(1, 5), rand(1, 4));
    }
    ctx.strokeStyle = "rgba(65,58,54,.16)";
    ctx.lineWidth = 2;
    for (let y = 0; y < h; y += 64) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }
  });
  texture.repeat.set(1, 50);
  return texture;
}

function makeFacadeTexture(variant) {
  return canvasTexture(256, 512, (ctx, w, h) => {
    const bases = ["#202d43", "#27354b", "#1d293d", "#2d374a"];
    ctx.fillStyle = bases[variant % bases.length];
    ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = "rgba(255,255,255,.035)";
    for (let x = 0; x < w; x += 16) ctx.fillRect(x, 0, 1, h);
    for (let y = 0; y < h; y += 16) ctx.fillRect(0, y, w, 1);
    const cols = 6;
    const rows = 13;
    const padX = 14;
    const padY = 13;
    const cellW = (w - padX * 2) / cols;
    const cellH = (h - padY * 2) / rows;
    for (let yy = 0; yy < rows; yy++) {
      for (let xx = 0; xx < cols; xx++) {
        const lit = Math.random();
        let color = "rgba(12,20,33,.9)";
        if (lit > 0.67) color = pick(["#ffd18a", "#ffb35c", "#ffe1a6", "#a8d7cc", "#f5a066"]);
        else if (lit > 0.47) color = pick(["#5f7892", "#4d647d", "#89938f"]);
        ctx.fillStyle = color;
        ctx.fillRect(padX + xx * cellW + 3, padY + yy * cellH + 3, cellW - 7, cellH - 7);
        if (lit > 0.67) {
          ctx.fillStyle = "rgba(255,214,140,.18)";
          ctx.fillRect(padX + xx * cellW + 1, padY + yy * cellH + 1, cellW - 3, cellH - 3);
        }
        ctx.strokeStyle = "rgba(6,11,20,.34)";
        ctx.strokeRect(padX + xx * cellW + 3, padY + yy * cellH + 3, cellW - 7, cellH - 7);
      }
    }
    const grad = ctx.createLinearGradient(0, 0, 0, h);
    grad.addColorStop(0, "rgba(255,160,110,.08)");
    grad.addColorStop(1, "rgba(0,0,0,.26)");
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
  });
}

function makeSignTexture(text, bg = "#ff6738", fg = "#fff4e3") {
  return canvasTexture(512, 160, (ctx, w, h) => {
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = "rgba(255,255,255,.25)";
    ctx.lineWidth = 6;
    ctx.strokeRect(8, 8, w - 16, h - 16);
    ctx.fillStyle = fg;
    ctx.font = "700 63px Arial Black, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(text, w / 2, h / 2 + 3);
  });
}

function makeCloudTexture() {
  const texture = canvasTexture(256, 128, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h);
    for (let i = 0; i < 15; i++) {
      const x = rand(20, w - 20);
      const y = rand(30, h - 25);
      const r = rand(14, 42);
      const grad = ctx.createRadialGradient(x, y, 0, x, y, r);
      grad.addColorStop(0, "rgba(255,247,231,.18)");
      grad.addColorStop(1, "rgba(255,247,231,0)");
      ctx.fillStyle = grad;
      ctx.fillRect(x - r, y - r, r * 2, r * 2);
    }
  });
  return texture;
}

export class Environment {
  constructor(scene, renderer) {
    this.scene = scene;
    this.renderer = renderer;
    this.trackChunks = [];
    this.buildings = [];
    this.gantries = [];
    this.clouds = [];
    this.dust = null;
    this.ballastTexture = makeBallastTexture();
    this.concreteTexture = makeConcreteTexture();
    this.clock = 0;
    this.build();
  }

  build() {
    const scene = this.scene;
    scene.fog = new THREE.Fog(0xe3a789, 72, 300);

    this.buildSky();
    this.buildLights();
    this.buildGround();
    this.buildRail();
    this.buildTrackChunks();
    this.buildCity();
    this.buildGantries();
    this.buildCatenary();
    this.buildClouds();
    this.buildDust();
  }

  buildSky() {
    const skyGeo = new THREE.SphereGeometry(420, 32, 20);
    const skyMat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      uniforms: {
        topColor: { value: new THREE.Color("#526d9e") },
        midColor: { value: new THREE.Color("#dc8768") },
        horizonColor: { value: new THREE.Color("#ffc39b") },
        sunColor: { value: new THREE.Color("#fff2c7") },
        sunDirection: { value: new THREE.Vector3(0.34, 0.19, -0.92).normalize() },
      },
      vertexShader: `
        varying vec3 vWorldPosition;
        void main() {
          vec4 worldPosition = modelMatrix * vec4(position, 1.0);
          vWorldPosition = worldPosition.xyz;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform vec3 topColor;
        uniform vec3 midColor;
        uniform vec3 horizonColor;
        uniform vec3 sunColor;
        uniform vec3 sunDirection;
        varying vec3 vWorldPosition;
        void main() {
          vec3 dir = normalize(vWorldPosition);
          float h = clamp(dir.y, -0.1, 1.0);
          vec3 color = mix(horizonColor, midColor, smoothstep(0.0, 0.22, h));
          color = mix(color, topColor, smoothstep(0.18, 0.72, h));
          float sunDot = max(dot(dir, sunDirection), 0.0);
          float sun = pow(sunDot, 420.0);
          float glow = pow(sunDot, 12.0);
          color += sunColor * sun * 1.5 + sunColor * glow * 0.22;
          float haze = smoothstep(0.11, -0.02, h) * 0.18;
          color = mix(color, horizonColor, haze);
          gl_FragColor = vec4(color, 1.0);
        }
      `,
    });
    const sky = new THREE.Mesh(skyGeo, skyMat);
    sky.renderOrder = -10;
    scene.add(sky);
    this.sky = sky;

    const sun = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: canvasTexture(128, 128, (ctx, w, h) => {
          const grad = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
          grad.addColorStop(0, "rgba(255,250,225,1)");
          grad.addColorStop(0.28, "rgba(255,238,176,.95)");
          grad.addColorStop(1, "rgba(255,206,132,0)");
          ctx.fillStyle = grad;
          ctx.fillRect(0, 0, w, h);
        }),
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        fog: false,
      }),
    );
    sun.scale.set(50, 50, 1);
    sun.position.set(118, 62, -310);
    scene.add(sun);
  }

  buildLights() {
    const hemi = new THREE.HemisphereLight(0xffe4c1, 0x3a4a60, 2.15);
    this.scene.add(hemi);

    const key = new THREE.DirectionalLight(0xffbd8b, 3.35);
    key.position.set(-22, 36, 18);
    key.target.position.set(2, 0, -30);
    key.castShadow = true;
    key.shadow.mapSize.set(1536, 1536);
    key.shadow.camera.left = -28;
    key.shadow.camera.right = 28;
    key.shadow.camera.top = 28;
    key.shadow.camera.bottom = -10;
    key.shadow.camera.near = 1;
    key.shadow.camera.far = 100;
    key.shadow.bias = -0.0008;
    key.shadow.normalBias = 0.035;
    this.scene.add(key, key.target);
    this.keyLight = key;

    const rim = new THREE.DirectionalLight(0x88b9d8, 1.15);
    rim.position.set(24, 16, -45);
    rim.target.position.set(0, 1, 0);
    this.scene.add(rim, rim.target);

    const bounce = new THREE.PointLight(0xff9e65, 12, 26, 2);
    bounce.position.set(-3, 1.8, 4);
    this.scene.add(bounce);
    this.bounceLight = bounce;
  }

  buildGround() {
    const groundMat = new THREE.MeshStandardMaterial({
      map: this.ballastTexture,
      color: 0xb3aaa1,
      roughness: 0.97,
      metalness: 0.02,
    });
    const ground = new THREE.Mesh(new THREE.PlaneGeometry(14.8, TRACK_AHEAD + 50), groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.set(0, -0.015, -TRACK_AHEAD / 2 + 24);
    ground.receiveShadow = true;
    this.scene.add(ground);
    this.ground = ground;

    const walkMat = new THREE.MeshStandardMaterial({
      map: this.concreteTexture,
      color: 0xc1ad99,
      roughness: 0.92,
    });
    for (const side of [-1, 1]) {
      const walk = new THREE.Mesh(new THREE.BoxGeometry(3.1, 0.22, TRACK_AHEAD + 40), walkMat);
      walk.position.set(side * 6.9, 0.1, -TRACK_AHEAD / 2 + 20);
      walk.receiveShadow = true;
      this.scene.add(walk);

      const curb = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.34, TRACK_AHEAD + 40), new THREE.MeshStandardMaterial({ color: 0xd8c3ab, roughness: 0.9 }));
      curb.position.set(side * 5.36, 0.12, -TRACK_AHEAD / 2 + 20);
      curb.receiveShadow = true;
      this.scene.add(curb);

      const wall = new THREE.Mesh(
        new THREE.BoxGeometry(0.26, 0.92, TRACK_AHEAD + 40),
        new THREE.MeshStandardMaterial({ map: this.concreteTexture, color: 0xa58f7e, roughness: 0.96 }),
      );
      wall.position.set(side * 8.55, 0.44, -TRACK_AHEAD / 2 + 20);
      this.scene.add(wall);
    }
  }

  buildRail() {
    const railMat = new THREE.MeshStandardMaterial({ color: 0x737b83, roughness: 0.28, metalness: 0.92 });
    const railGeo = new THREE.BoxGeometry(0.085, 0.11, TRACK_AHEAD + 44);
    this.railMeshes = [];
    for (const lane of LANE_X) {
      for (const offset of [-0.62, 0.62]) {
        const rail = new THREE.Mesh(railGeo, railMat);
        rail.position.set(lane + offset, 0.16, -TRACK_AHEAD / 2 + 20);
        rail.receiveShadow = true;
        this.scene.add(rail);
        this.railMeshes.push(rail);
      }
    }

    const thirdRailMat = new THREE.MeshStandardMaterial({ color: 0x8f5c42, roughness: 0.5, metalness: 0.6 });
    for (const lane of LANE_X) {
      const rail = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.08, TRACK_AHEAD + 44), thirdRailMat);
      rail.position.set(lane + 0.26, 0.23, -TRACK_AHEAD / 2 + 20);
      this.scene.add(rail);
    }
  }

  buildTrackChunks() {
    const sleeperGeo = new THREE.BoxGeometry(1.95, 0.1, 0.34);
    const sleeperMat = new THREE.MeshStandardMaterial({ color: 0x6c5543, roughness: 0.93 });
    const boltGeo = new THREE.BoxGeometry(0.1, 0.12, 0.1);
    const boltMat = new THREE.MeshStandardMaterial({ color: 0x41454a, metalness: 0.8, roughness: 0.42 });
    const lampPostMat = new THREE.MeshStandardMaterial({ color: 0x253044, metalness: 0.7, roughness: 0.45 });
    const lampGlowMat = new THREE.MeshStandardMaterial({ color: 0xffe9bd, emissive: 0xffb864, emissiveIntensity: 2.6 });

    const chunkLength = 24;
    const total = 13;
    const sleeperCount = 10;

    for (let i = 0; i < total; i++) {
      const chunk = new THREE.Group();
      chunk.position.z = 22 - i * chunkLength;

      const sleepers = new THREE.InstancedMesh(sleeperGeo, sleeperMat, sleeperCount * LANE_X.length);
      sleepers.receiveShadow = true;
      const dummy = new THREE.Object3D();
      let n = 0;
      for (let s = 0; s < sleeperCount; s++) {
        for (const lane of LANE_X) {
          dummy.position.set(lane, 0.075, -s * 2.4);
          dummy.rotation.y = rand(-0.012, 0.012);
          dummy.updateMatrix();
          sleepers.setMatrixAt(n++, dummy.matrix);
        }
      }
      sleepers.instanceMatrix.needsUpdate = true;
      chunk.add(sleepers);

      const bolts = new THREE.InstancedMesh(boltGeo, boltMat, sleeperCount * 6);
      n = 0;
      for (let s = 0; s < sleeperCount; s++) {
        for (const lane of LANE_X) {
          for (const offset of [-0.62, 0.62]) {
            dummy.position.set(lane + offset, 0.16, -s * 2.4);
            dummy.updateMatrix();
            bolts.setMatrixAt(n++, dummy.matrix);
          }
        }
      }
      bolts.instanceMatrix.needsUpdate = true;
      chunk.add(bolts);

      for (const side of [-1, 1]) {
        const pole = new THREE.Group();
        const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.095, 3.6, 6), lampPostMat);
        stem.position.y = 1.8;
        pole.add(stem);
        const arm = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.07, 0.08), lampPostMat);
        arm.position.set(-side * 0.4, 3.52, 0);
        pole.add(arm);
        const shade = new THREE.Mesh(new THREE.ConeGeometry(0.25, 0.22, 10, 1, true), lampPostMat);
        shade.position.set(-side * 0.82, 3.42, 0);
        shade.rotation.z = Math.PI;
        pole.add(shade);
        const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.095, 8, 6), lampGlowMat);
        bulb.position.set(-side * 0.82, 3.3, 0);
        pole.add(bulb);
        pole.position.set(side * 7.1, 0.2, -3);
        chunk.add(pole);
      }

      const cabinet = new THREE.Mesh(
        new THREE.BoxGeometry(0.7, 1.05, 0.5),
        new THREE.MeshStandardMaterial({ color: 0x687072, roughness: 0.7, metalness: 0.35 }),
      );
      cabinet.position.set(i % 2 ? 6.15 : -6.15, 0.64, -14);
      cabinet.castShadow = true;
      chunk.add(cabinet);

      this.scene.add(chunk);
      this.trackChunks.push(chunk);
    }
    this.chunkSpan = total * chunkLength;
  }

  buildCity() {
    const facadeMaps = [];
    for (let i = 0; i < 4; i++) facadeMaps.push(makeFacadeTexture(i));
    const neonColors = [0xff6b3d, 0x72e0c4, 0xffc83e, 0x6aa8ff, 0xff83b0];
    const signLabels = ["HOTEL", "NOODLES", "METRO", "24H", "CAFE", "ARCADE"];
    const signTextures = signLabels.map((label, i) =>
      makeSignTexture(label, ["#d94d29", "#1d5b59", "#db8d20", "#253c73", "#922d5e", "#2d5d47"][i], "#fff4e3"),
    );

    const count = 17;
    for (const side of [-1, 1]) {
      for (let i = 0; i < count; i++) {
        const group = new THREE.Group();
        const width = rand(5.8, 11);
        const depth = rand(7, 15);
        const height = rand(9, 30);
        const map = pick(facadeMaps).clone();
        map.needsUpdate = true;
        map.repeat.set(Math.max(1, Math.round(width / 4)), Math.max(1, Math.round(height / 9)));
        const tint = pick([0xffffff, 0xe3c5ad, 0xb9c6cf, 0xffd9bd, 0xb4aeb5]);
        const bodyMat = new THREE.MeshStandardMaterial({
          map,
          color: tint,
          roughness: 0.82,
          metalness: 0.05,
          emissive: 0xff9e5f,
          emissiveMap: map,
          emissiveIntensity: 0.17,
        });
        const body = new THREE.Mesh(new THREE.BoxGeometry(width, height, depth), bodyMat);
        body.position.y = height / 2;
        group.add(body);

        const roof = new THREE.Mesh(
          new THREE.BoxGeometry(width + 0.6, 0.45, depth + 0.6),
          new THREE.MeshStandardMaterial({ color: 0x6b635f, roughness: 0.9 }),
        );
        roof.position.y = height + 0.2;
        group.add(roof);

        if (Math.random() > 0.55) {
          const tank = new THREE.Mesh(
            new THREE.CylinderGeometry(0.75, 0.9, 2.1, 8),
            new THREE.MeshStandardMaterial({ color: 0x7b6a5a, roughness: 0.9 }),
          );
          tank.position.set(rand(-width * 0.22, width * 0.22), height + 1.4, rand(-depth * 0.18, depth * 0.18));
          group.add(tank);
        }

        if (Math.random() > 0.35) {
          const antenna = new THREE.Mesh(
            new THREE.CylinderGeometry(0.035, 0.05, rand(2, 6), 4),
            new THREE.MeshStandardMaterial({ color: 0x3d4147 }),
          );
          antenna.position.set(rand(-width * 0.3, width * 0.3), height + 3.2, 0);
          group.add(antenna);
          const beacon = new THREE.Mesh(
            new THREE.SphereGeometry(0.095, 6, 5),
            new THREE.MeshStandardMaterial({ color: 0xff5d4d, emissive: 0xff3322, emissiveIntensity: 3 }),
          );
          beacon.position.copy(antenna.position);
          beacon.position.y += 2.7;
          group.add(beacon);
        }

        if (Math.random() > 0.58) {
          const sign = new THREE.Mesh(
            new THREE.PlaneGeometry(rand(2.8, 4.4), 1.28),
            new THREE.MeshBasicMaterial({ map: pick(signTextures), transparent: true, toneMapped: false, side: THREE.DoubleSide }),
          );
          sign.position.set(side * (width / 2 + 0.03), rand(3.6, Math.min(7, height - 2)), -depth * 0.08);
          sign.rotation.y = side > 0 ? -Math.PI / 2 : Math.PI / 2;
          group.add(sign);
          const glow = new THREE.PointLight(neonColors[Math.floor(Math.random() * neonColors.length)], 1.8, 7, 2);
          glow.position.copy(sign.position);
          glow.position.x -= side * 0.4;
          group.add(glow);
        }

        group.position.x = side * rand(11, 22);
        group.position.z = 16 - i * 22 + rand(-6, 6);
        group.userData.side = side;
        group.userData.baseX = group.position.x;
        this.scene.add(group);
        this.buildings.push(group);
      }
    }
  }

  buildGantries() {
    const steel = new THREE.MeshStandardMaterial({ color: 0x334154, roughness: 0.52, metalness: 0.62 });
    const signMats = [
      new THREE.MeshBasicMaterial({ map: makeSignTexture("METRO", "#173b53", "#7ce3c4"), transparent: true, toneMapped: false, side: THREE.DoubleSide }),
      new THREE.MeshBasicMaterial({ map: makeSignTexture("CITY 07", "#a53920", "#fff4e3"), transparent: true, toneMapped: false, side: THREE.DoubleSide }),
      new THREE.MeshBasicMaterial({ map: makeSignTexture("EXPRESS", "#233f66", "#ffc83e"), transparent: true, toneMapped: false, side: THREE.DoubleSide }),
    ];
    const stripMat = new THREE.MeshStandardMaterial({ color: 0xd4fff2, emissive: 0x8ff7d7, emissiveIntensity: 3.2 });
    const positions = [-34, -116, -198, -282];
    for (let i = 0; i < positions.length; i++) {
      const group = new THREE.Group();
      const span = 14.2;
      for (const side of [-1, 1]) {
        const post = new THREE.Mesh(new THREE.BoxGeometry(0.32, 6.6, 0.32), steel);
        post.position.set(side * 6.7, 3.3, 0);
        group.add(post);
        const foot = new THREE.Mesh(new THREE.BoxGeometry(0.8, 0.25, 0.8), steel);
        foot.position.set(side * 6.7, 0.12, 0);
        group.add(foot);
      }
      const top = new THREE.Mesh(new THREE.BoxGeometry(span, 0.28, 0.34), steel);
      top.position.y = 6.55;
      group.add(top);
      const lower = new THREE.Mesh(new THREE.BoxGeometry(span - 1, 0.12, 0.2), steel);
      lower.position.y = 5.92;
      group.add(lower);

      const strip = new THREE.Mesh(new THREE.BoxGeometry(5.5, 0.07, 0.08), stripMat);
      strip.position.set(0, 6.32, 0.2);
      group.add(strip);

      const sign = new THREE.Mesh(new THREE.PlaneGeometry(2.7, 0.84), signMats[i % signMats.length]);
      sign.position.set(0, 6.45, 0.2);
      group.add(sign);

      const signal = new THREE.Mesh(
        new THREE.BoxGeometry(0.34, 0.72, 0.28),
        new THREE.MeshStandardMaterial({ color: 0x1b252f, roughness: 0.5 }),
      );
      signal.position.set(-4.2, 4.95, 0);
      group.add(signal);
      const lamp = new THREE.Mesh(
        new THREE.SphereGeometry(0.11, 8, 6),
        new THREE.MeshStandardMaterial({ color: 0x7cf0b5, emissive: 0x4be29e, emissiveIntensity: 3.5 }),
      );
      lamp.position.set(-4.2, 5.08, 0.16);
      group.add(lamp);

      group.position.z = positions[i];
      this.scene.add(group);
      this.gantries.push(group);
    }
    this.gantrySpan = 82;
  }

  buildCatenary() {
    const wireMat = new THREE.MeshBasicMaterial({ color: 0x252c34, transparent: true, opacity: 0.72 });
    for (const lane of LANE_X) {
      for (let i = 0; i < 3; i++) {
        const wire = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, TRACK_AHEAD + 50, 3), wireMat);
        wire.rotation.x = Math.PI / 2;
        wire.position.set(lane + (i - 1) * 0.15, 5.3 + i * 0.16, -TRACK_AHEAD / 2 + 20);
        this.scene.add(wire);
      }
    }
  }

  buildClouds() {
    const cloudMat = new THREE.MeshBasicMaterial({
      map: makeCloudTexture(),
      transparent: true,
      depthWrite: false,
      opacity: 0.45,
      fog: false,
      blending: THREE.AdditiveBlending,
    });
    for (let i = 0; i < 9; i++) {
      const cloud = new THREE.Mesh(new THREE.PlaneGeometry(rand(38, 90), rand(11, 23)), cloudMat);
      cloud.position.set(rand(-150, 150), rand(45, 88), -rand(210, 350));
      cloud.userData.speed = rand(0.2, 0.6);
      this.scene.add(cloud);
      this.clouds.push(cloud);
    }
  }

  buildDust() {
    const count = 180;
    const positions = new Float32Array(count * 3);
    const sizes = new Float32Array(count);
    for (let i = 0; i < count; i++) {
      positions[i * 3] = rand(-9, 9);
      positions[i * 3 + 1] = rand(0.4, 6.5);
      positions[i * 3 + 2] = rand(-TRACK_AHEAD, 14);
      sizes[i] = rand(0.4, 1.1);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({
      color: 0xffd6ac,
      size: 0.045,
      transparent: true,
      opacity: 0.45,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      sizeAttenuation: true,
    });
    this.dust = new THREE.Points(geo, mat);
    this.scene.add(this.dust);
    this.dustCount = count;
  }

  update(dt, speed, distance) {
    this.clock += dt;
    const move = speed * dt;
    this.ballastTexture.offset.y -= move * 0.018;

    for (const chunk of this.trackChunks) {
      chunk.position.z += move;
      if (chunk.position.z > 42) chunk.position.z -= this.chunkSpan;
    }

    for (const building of this.buildings) {
      building.position.z += move;
      if (building.position.z > 38) {
        building.position.z -= 17 * 22;
        building.position.x = building.userData.side * rand(11, 22);
        building.scale.y = rand(0.82, 1.06);
      }
    }

    for (const gantry of this.gantries) {
      gantry.position.z += move;
      if (gantry.position.z > 34) gantry.position.z -= this.gantrySpan * 4;
    }

    for (const cloud of this.clouds) {
      cloud.position.z += move * 0.012 * cloud.userData.speed;
      cloud.position.x += Math.sin(this.clock * 0.04 + cloud.position.z) * dt * 0.08;
      if (cloud.position.z > -190) {
        cloud.position.z -= 170;
        cloud.position.x = rand(-150, 150);
      }
    }

    if (this.dust) {
      const positions = this.dust.geometry.attributes.position.array;
      for (let i = 0; i < this.dustCount; i++) {
        positions[i * 3 + 2] += move * 0.7;
        positions[i * 3 + 1] += Math.sin(this.clock * 1.3 + i) * dt * 0.06;
        if (positions[i * 3 + 2] > 14) {
          positions[i * 3 + 2] -= TRACK_AHEAD + 14;
          positions[i * 3] = rand(-9, 9);
          positions[i * 3 + 1] = rand(0.4, 6.5);
        }
      }
      this.dust.geometry.attributes.position.needsUpdate = true;
    }

    if (this.bounceLight) {
      this.bounceLight.intensity = 9 + Math.sin(this.clock * 3.4) * 1.2;
    }

    const speedNorm = THREE.MathUtils.clamp((speed - 16) / 24, 0, 1);
    this.keyLight.intensity = 3.35 - speedNorm * 0.25;
    this.renderer.toneMappingExposure = 1.05 + Math.sin(distance * 0.01) * 0.01;
  }
}

import * as THREE from "three";
import { RoundedBoxGeometry } from "three/addons/geometries/RoundedBoxGeometry.js";

const LANE_X = [-2.4, 0, 2.4];

const MAT = {
  jacket: new THREE.MeshStandardMaterial({ color: 0xff5e36, roughness: 0.7 }),
  jacketDark: new THREE.MeshStandardMaterial({ color: 0xd94420, roughness: 0.72 }),
  cream: new THREE.MeshStandardMaterial({ color: 0xffe6c7, roughness: 0.72 }),
  pants: new THREE.MeshStandardMaterial({ color: 0x1c2b49, roughness: 0.78 }),
  pantsLight: new THREE.MeshStandardMaterial({ color: 0x263b61, roughness: 0.76 }),
  skin: new THREE.MeshStandardMaterial({ color: 0xc9865b, roughness: 0.68 }),
  skinDark: new THREE.MeshStandardMaterial({ color: 0x9f6442, roughness: 0.7 }),
  hair: new THREE.MeshStandardMaterial({ color: 0x241b1a, roughness: 0.9 }),
  teal: new THREE.MeshStandardMaterial({ color: 0x28bda3, roughness: 0.63 }),
  tealDark: new THREE.MeshStandardMaterial({ color: 0x158a78, roughness: 0.7 }),
  gold: new THREE.MeshStandardMaterial({ color: 0xffc53d, roughness: 0.48, metalness: 0.06 }),
  black: new THREE.MeshStandardMaterial({ color: 0x111a2a, roughness: 0.55 }),
  white: new THREE.MeshStandardMaterial({ color: 0xfffbef, roughness: 0.5 }),
  sole: new THREE.MeshStandardMaterial({ color: 0xfff1dc, roughness: 0.45 }),
  soleAccent: new THREE.MeshStandardMaterial({ color: 0xff6a3b, roughness: 0.6 }),
};

function capsule(radius, length, material, segments = 8) {
  const mesh = new THREE.Mesh(new THREE.CapsuleGeometry(radius, length, 4, segments), material);
  mesh.castShadow = true;
  return mesh;
}

function box(width, height, depth, material, radius = 0.055) {
  const geometry =
    radius > 0
      ? new RoundedBoxGeometry(width, height, depth, 3, radius)
      : new THREE.BoxGeometry(width, height, depth);
  const mesh = new THREE.Mesh(geometry, material);
  mesh.castShadow = true;
  return mesh;
}

export class Player {
  constructor(scene) {
    this.scene = scene;
    this.root = new THREE.Group();
    this.visual = new THREE.Group();
    this.root.add(this.visual);
    scene.add(this.root);

    this.lane = 1;
    this.targetLane = 1;
    this.x = 0;
    this.y = 0;
    this.vy = 0;
    this.jumpHeld = false;
    this.sliding = false;
    this.slideTimer = 0;
    this.slideQueued = false;
    this.runPhase = 0;
    this.grounded = true;
    this.dead = false;
    this.deadTime = 0;
    this.laneVelocity = 0;

    this.buildCharacter();
    this.buildShadow();
    this.root.position.set(0, 0, 0);
  }

  buildCharacter() {
    const v = this.visual;

    // Hips and a little sag of the pants.
    const hips = box(0.63, 0.32, 0.43, MAT.pants, 0.12);
    hips.position.y = 0.99;
    v.add(hips);

    const torso = new THREE.Mesh(new THREE.SphereGeometry(0.47, 18, 14), MAT.jacket);
    torso.scale.set(1.02, 1.28, 0.77);
    torso.position.y = 1.46;
    torso.castShadow = true;
    v.add(torso);

    const belly = new THREE.Mesh(new THREE.SphereGeometry(0.4, 16, 12), MAT.jacket);
    belly.scale.set(1.02, 0.86, 0.86);
    belly.position.set(0, 1.24, -0.03);
    belly.castShadow = true;
    v.add(belly);

    // Zipper and drawstrings.
    const zipper = box(0.035, 0.75, 0.025, MAT.jacketDark, 0.01);
    zipper.position.set(0, 1.46, -0.368);
    zipper.rotation.x = 0.05;
    v.add(zipper);
    for (const side of [-1, 1]) {
      const string = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.24, 5), MAT.cream);
      string.position.set(side * 0.1, 1.71, -0.34);
      string.rotation.z = side * 0.18;
      v.add(string);
      const tip = new THREE.Mesh(new THREE.SphereGeometry(0.022, 6, 5), MAT.gold);
      tip.position.set(side * 0.123, 1.59, -0.34);
      v.add(tip);
    }

    // Hood bunched behind the neck.
    const hood = new THREE.Mesh(new THREE.TorusGeometry(0.31, 0.1, 8, 18, Math.PI), MAT.jacketDark);
    hood.position.set(0, 1.76, 0.2);
    hood.rotation.x = 1.18;
    hood.rotation.z = Math.PI;
    hood.castShadow = true;
    v.add(hood);
    const hoodInner = new THREE.Mesh(new THREE.TorusGeometry(0.24, 0.055, 7, 16, Math.PI), MAT.cream);
    hoodInner.position.set(0, 1.78, 0.14);
    hoodInner.rotation.x = 1.18;
    hoodInner.rotation.z = Math.PI;
    v.add(hoodInner);

    // Head.
    const head = new THREE.Group();
    head.position.y = 2.02;
    const face = new THREE.Mesh(new THREE.SphereGeometry(0.275, 18, 14), MAT.skin);
    face.scale.set(0.94, 1.05, 0.96);
    face.castShadow = true;
    head.add(face);

    const earL = new THREE.Mesh(new THREE.SphereGeometry(0.065, 8, 6), MAT.skinDark);
    earL.position.set(-0.26, -0.01, 0);
    earL.scale.set(0.55, 1, 0.8);
    head.add(earL);
    const earR = earL.clone();
    earR.position.x = 0.26;
    head.add(earR);

    const eyeGeo = new THREE.SphereGeometry(0.035, 8, 6);
    for (const side of [-1, 1]) {
      const eye = new THREE.Mesh(eyeGeo, MAT.black);
      eye.position.set(side * 0.093, 0.025, -0.252);
      eye.scale.set(0.85, 1.25, 0.45);
      head.add(eye);
    }
    const browGeo = new THREE.BoxGeometry(0.09, 0.018, 0.02);
    for (const side of [-1, 1]) {
      const brow = new THREE.Mesh(browGeo, MAT.hair);
      brow.position.set(side * 0.095, 0.092, -0.26);
      brow.rotation.z = side * -0.12;
      head.add(brow);
    }
    const nose = new THREE.Mesh(new THREE.SphereGeometry(0.045, 8, 6), MAT.skinDark);
    nose.position.set(0, -0.02, -0.274);
    nose.scale.set(0.8, 0.7, 0.7);
    head.add(nose);
    const smile = new THREE.Mesh(new THREE.TorusGeometry(0.052, 0.009, 5, 10, Math.PI), MAT.skinDark);
    smile.position.set(0, -0.09, -0.263);
    smile.rotation.z = Math.PI;
    head.add(smile);

    // Beanie.
    const beanie = new THREE.Mesh(new THREE.SphereGeometry(0.292, 18, 12, 0, Math.PI * 2, 0, Math.PI / 2), MAT.teal);
    beanie.position.y = 0.06;
    beanie.scale.set(1.02, 1.12, 1.02);
    beanie.castShadow = true;
    head.add(beanie);
    const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.296, 0.296, 0.11, 18), MAT.tealDark);
    brim.position.y = 0.06;
    head.add(brim);
    const pom = new THREE.Mesh(new THREE.SphereGeometry(0.07, 8, 6), MAT.gold);
    pom.position.y = 0.39;
    head.add(pom);

    // Headphones: band and ear cups.
    const band = new THREE.Mesh(new THREE.TorusGeometry(0.3, 0.025, 6, 18, Math.PI), MAT.cream);
    band.position.y = 0.03;
    band.rotation.z = Math.PI;
    head.add(band);
    for (const side of [-1, 1]) {
      const cup = new THREE.Mesh(new THREE.CylinderGeometry(0.088, 0.088, 0.075, 10), MAT.cream);
      cup.position.set(side * 0.292, -0.01, 0);
      cup.rotation.z = Math.PI / 2;
      head.add(cup);
      const cupDark = new THREE.Mesh(new THREE.CylinderGeometry(0.065, 0.065, 0.08, 10), MAT.jacketDark);
      cupDark.position.set(side * 0.307, -0.01, 0);
      cupDark.rotation.z = Math.PI / 2;
      head.add(cupDark);
    }

    v.add(head);
    this.head = head;

    // Arms with pivots at the shoulders.
    this.arms = [];
    for (const side of [-1, 1]) {
      const arm = new THREE.Group();
      arm.position.set(side * 0.47, 1.63, 0);
      arm.rotation.z = side * 0.17;
      const sleeve = capsule(0.115, 0.36, MAT.jacket, 7);
      sleeve.position.y = -0.21;
      arm.add(sleeve);
      const cuff = new THREE.Mesh(new THREE.CylinderGeometry(0.095, 0.085, 0.09, 8), MAT.cream);
      cuff.position.y = -0.46;
      arm.add(cuff);
      const hand = new THREE.Mesh(new THREE.SphereGeometry(0.082, 8, 7), MAT.skin);
      hand.position.y = -0.55;
      hand.castShadow = true;
      arm.add(hand);
      v.add(arm);
      this.arms.push(arm);
    }

    // Legs with hip pivots.
    this.legs = [];
    for (const side of [-1, 1]) {
      const leg = new THREE.Group();
      leg.position.set(side * 0.19, 0.92, 0);
      const thigh = capsule(0.125, 0.3, MAT.pants, 7);
      thigh.position.y = -0.24;
      leg.add(thigh);
      const shin = capsule(0.102, 0.3, MAT.pantsLight, 7);
      shin.position.y = -0.55;
      leg.add(shin);
      const shoe = box(0.25, 0.16, 0.43, MAT.sole, 0.07);
      shoe.position.set(0, -0.78, -0.1);
      leg.add(shoe);
      const toe = box(0.23, 0.08, 0.15, MAT.soleAccent, 0.04);
      toe.position.set(0, -0.82, -0.33);
      leg.add(toe);
      v.add(leg);
      this.legs.push(leg);
    }

    // Backpack — the hero detail from the default chase camera.
    const pack = new THREE.Group();
    pack.position.set(0, 1.35, 0.46);
    const packBody = box(0.56, 0.7, 0.28, MAT.teal, 0.12);
    pack.add(packBody);
    const packFlap = box(0.5, 0.26, 0.31, MAT.tealDark, 0.07);
    packFlap.position.set(0, 0.24, 0.01);
    pack.add(packFlap);
    const packPocket = box(0.34, 0.27, 0.08, MAT.cream, 0.04);
    packPocket.position.set(0, -0.16, 0.17);
    pack.add(packPocket);
    const packPatch = new THREE.Mesh(new THREE.CircleGeometry(0.085, 12), MAT.gold);
    packPatch.position.set(0.16, 0.04, 0.173);
    pack.add(packPatch);
    const packPatchStripe = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.035, 0.01), MAT.jacketDark);
    packPatchStripe.position.set(0.16, 0.04, 0.181);
    pack.add(packPatchStripe);
    const handle = new THREE.Mesh(new THREE.TorusGeometry(0.075, 0.018, 5, 10, Math.PI), MAT.cream);
    handle.position.set(0, 0.39, 0.02);
    pack.add(handle);
    for (const side of [-1, 1]) {
      const strap = box(0.08, 0.72, 0.075, MAT.gold, 0.03);
      strap.position.set(side * 0.29, 0.03, -0.32);
      strap.rotation.x = -0.1;
      pack.add(strap);
    }
    v.add(pack);
    this.backpack = pack;
  }

  buildShadow() {
    this.shadow = new THREE.Mesh(
      new THREE.CircleGeometry(0.5, 24),
      new THREE.MeshBasicMaterial({ color: 0x0c1220, transparent: true, opacity: 0.27, depthWrite: false }),
    );
    this.shadow.rotation.x = -Math.PI / 2;
    this.shadow.position.y = 0.018;
    this.shadow.renderOrder = 2;
    this.scene.add(this.shadow);
  }

  reset() {
    this.lane = 1;
    this.targetLane = 1;
    this.x = 0;
    this.y = 0;
    this.vy = 0;
    this.sliding = false;
    this.slideTimer = 0;
    this.slideQueued = false;
    this.grounded = true;
    this.dead = false;
    this.deadTime = 0;
    this.runPhase = 0;
    this.root.position.set(0, 0, 0);
    this.root.rotation.set(0, 0, 0);
    this.visual.position.set(0, 0, 0);
    this.visual.rotation.set(0, 0, 0);
    this.shadow.visible = true;
    this.shadow.scale.setScalar(1);
    this.shadow.material.opacity = 0.27;
  }

  moveLeft() {
    if (this.dead) return false;
    if (this.targetLane > 0) {
      this.targetLane -= 1;
      this.lane = this.targetLane;
      return true;
    }
    return false;
  }

  moveRight() {
    if (this.dead) return false;
    if (this.targetLane < 2) {
      this.targetLane += 1;
      this.lane = this.targetLane;
      return true;
    }
    return false;
  }

  jump() {
    if (this.dead) return false;
    if (this.grounded) {
      this.vy = 8.6;
      this.grounded = false;
      this.sliding = false;
      this.slideTimer = 0;
      return true;
    }
    return false;
  }

  slide() {
    if (this.dead) return false;
    if (!this.grounded) {
      this.vy = Math.min(this.vy, -18);
      this.slideQueued = true;
      return true;
    }
    if (!this.sliding) {
      this.sliding = true;
      this.slideTimer = 0.68;
      return true;
    }
    this.slideTimer = Math.max(this.slideTimer, 0.45);
    return true;
  }

  die() {
    if (this.dead) return;
    this.dead = true;
    this.deadTime = 0;
    this.sliding = false;
    this.slideTimer = 0;
    this.vy = 3.4;
    this.grounded = false;
  }

  update(dt, speed, { menu = false } = {}) {
    const targetX = LANE_X[this.targetLane];
    const previousX = this.x;
    const lambda = this.dead ? 4 : 15;
    this.x = THREE.MathUtils.damp(this.x, targetX, lambda, dt);
    this.laneVelocity = (this.x - previousX) / Math.max(dt, 0.001);

    if (!this.dead) {
      this.vy -= 24 * dt;
      this.y += this.vy * dt;
      if (this.y <= 0) {
        this.y = 0;
        if (!this.grounded) {
          this.grounded = true;
          if (this.slideQueued) {
            this.slideQueued = false;
            this.sliding = true;
            this.slideTimer = 0.5;
          }
        }
        this.vy = 0;
      } else {
        this.grounded = false;
      }

      if (this.sliding) {
        this.slideTimer -= dt;
        if (this.slideTimer <= 0) this.sliding = false;
      }
    } else {
      this.deadTime += dt;
      this.vy -= 18 * dt;
      this.y = Math.max(0, this.y + this.vy * dt);
    }

    this.runPhase += dt * (menu ? 6.4 : 8.5 + speed * 0.24);
    this.root.position.x = this.x;
    this.root.position.y = this.y;

    const run = Math.sin(this.runPhase);
    const runAlt = Math.sin(this.runPhase + Math.PI);
    const bob = this.grounded && !this.sliding ? Math.abs(Math.sin(this.runPhase)) * 0.035 : 0;

    this.visual.position.y = bob;
    this.visual.position.z = 0;
    this.visual.rotation.set(0, 0, 0);
    this.visual.scale.set(1, 1, 1);

    if (this.dead) {
      const fall = Math.min(this.deadTime / 0.8, 1);
      this.visual.rotation.x = -fall * 1.4;
      this.visual.rotation.z = fall * 0.7;
      this.visual.rotation.y = this.deadTime * 1.3;
      this.visual.position.y = 0.12 - fall * 0.05;
      this.arms[0].rotation.x = -1.1 - fall * 1.5;
      this.arms[1].rotation.x = 0.7 + fall * 1.6;
      this.arms[0].rotation.z = -0.6;
      this.arms[1].rotation.z = 0.6;
      this.legs[0].rotation.x = -0.9 * fall;
      this.legs[1].rotation.x = 0.8 * fall;
      this.head.rotation.z = fall * 0.25;
    } else if (this.sliding) {
      const t = Math.min(1, (0.68 - this.slideTimer) / 0.12);
      this.visual.rotation.x = -1.33 * t;
      this.visual.position.y = 0.54 * t;
      this.visual.position.z = 0.26 * t;
      this.legs[0].rotation.x = -0.4;
      this.legs[1].rotation.x = 0.25;
      this.arms[0].rotation.x = -0.55;
      this.arms[1].rotation.x = -0.2;
      this.arms[0].rotation.z = -0.42;
      this.arms[1].rotation.z = 0.42;
      this.head.rotation.x = 0.36;
    } else if (!this.grounded) {
      this.visual.position.y += 0.02;
      this.legs[0].rotation.x = -0.68 + run * 0.1;
      this.legs[1].rotation.x = 0.55 - run * 0.1;
      this.arms[0].rotation.x = -1.8 + run * 0.08;
      this.arms[1].rotation.x = -1.8 - run * 0.08;
      this.arms[0].rotation.z = -0.42;
      this.arms[1].rotation.z = 0.42;
      this.head.rotation.x = -0.08;
    } else {
      this.legs[0].rotation.x = run * 0.82;
      this.legs[1].rotation.x = runAlt * 0.82;
      this.arms[0].rotation.x = runAlt * 0.78;
      this.arms[1].rotation.x = run * 0.78;
      this.arms[0].rotation.z = -0.17;
      this.arms[1].rotation.z = 0.17;
      this.head.rotation.x = 0;
      this.head.rotation.z = Math.sin(this.runPhase * 0.5) * 0.03;
    }

    const laneOffset = this.x / 2.4;
    this.visual.rotation.z += laneOffset * 0.13;
    this.visual.rotation.y += -this.laneVelocity * 0.008;
    if (!this.dead) {
      this.backpack.rotation.z = Math.sin(this.runPhase * 0.5) * 0.02 - laneOffset * 0.035;
    }

    this.shadow.position.x = this.x;
    const shadowScale = THREE.MathUtils.clamp(1 - this.y * 0.16, 0.62, 1);
    this.shadow.scale.setScalar(shadowScale);
    this.shadow.material.opacity = 0.27 * shadowScale;
    this.shadow.position.z = 0;
  }
}

