class ParticleBurst {
  constructor(scene, { color, size, count = 120, gravity = 12, life = 0.7 }) {
    this.count = count;
    this.gravity = gravity;
    this.life = life;
    this.particles = [];
    const positions = new Float32Array(count * 3);
    positions.fill(-999);
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    const material = new THREE.PointsMaterial({
      color,
      map: shared.glow,
      size,
      transparent: true,
      opacity: 0.95,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      sizeAttenuation: true,
    });
    this.points = new THREE.Points(geometry, material);
    this.points.frustumCulled = false;
    scene.add(this.points);
    for (let i = 0; i < count; i++) this.particles.push({ active: false, x: 0, y: -999, z: 0, vx: 0, vy: 0, vz: 0, age: 0 });
    this.cursor = 0;
  }

  spawn(position, amount = 6, power = 1) {
    const array = this.points.geometry.attributes.position.array;
    for (let i = 0; i < amount; i++) {
      const index = this.cursor++ % this.count;
      const particle = this.particles[index];
      particle.active = true;
      particle.age = 0;
      particle.x = position.x + rand(-0.13, 0.13);
      particle.y = position.y + rand(-0.16, 0.16);
      particle.z = position.z + rand(-0.13, 0.13);
      const angle = Math.random() * Math.PI * 2;
      const speed = rand(1.2, 4) * power;
      particle.vx = Math.cos(angle) * speed;
      particle.vy = rand(1.4, 5.5) * power;
      particle.vz = Math.sin(angle) * speed * 0.7;
      array[index * 3] = particle.x;
      array[index * 3 + 1] = particle.y;
      array[index * 3 + 2] = particle.z;
    }
    this.points.geometry.attributes.position.needsUpdate = true;
  }

  update(dt) {
    const array = this.points.geometry.attributes.position.array;
    let dirty = false;
    for (let i = 0; i < this.count; i++) {
      const p = this.particles[i];
      if (!p.active) continue;
      p.age += dt;
      if (p.age > this.life) {
        p.active = false;
        p.y = -999;
        array[i * 3 + 1] = -999;
        dirty = true;
        continue;
      }
      p.vy -= this.gravity * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.z += p.vz * dt;
      array[i * 3] = p.x;
      array[i * 3 + 1] = p.y;
      array[i * 3 + 2] = p.z;
      dirty = true;
    }
    if (dirty) this.points.geometry.attributes.position.needsUpdate = true;
  }
}

export class Course {
  constructor(scene) {
    this.scene = scene;
    this.obstacles = [];
    this.coins = [];
    this.powerups = [];
    this.debris = [];
    this.bonus = 0;
    this.coinsCollected = 0;
    this.coinStreak = 0;
    this.lastCoinAt = -10;
    this.magnetTimer = 0;
    this.goldBurst = new ParticleBurst(scene, { color: 0xffd45c, size: 0.18, count: 150, gravity: 11, life: 0.75 });
    this.crashBurst = new ParticleBurst(scene, { color: 0xff8d55, size: 0.28, count: 100, gravity: 18, life: 1.1 });
    this.sparkBurst = new ParticleBurst(scene, { color: 0x96ffe1, size: 0.26, count: 90, gravity: 6, life: 1.2 });
    this.onCoin = null;
    this.onPower = null;
    this.warningPhase = 0;
    this.powerupMileage = 260;
    this.trainSigns = [
      new THREE.MeshBasicMaterial({ map: makeTextTexture("EXPRESS 07", "#1b3c56", "#ffcf48"), toneMapped: false, transparent: true, side: THREE.DoubleSide }),
      new THREE.MeshBasicMaterial({ map: makeTextTexture("CITY LOOP", "#a83d24", "#fff2dc"), toneMapped: false, transparent: true, side: THREE.DoubleSide }),
      new THREE.MeshBasicMaterial({ map: makeTextTexture("NIGHT LINE", "#21463d", "#8af0ce"), toneMapped: false, transparent: true, side: THREE.DoubleSide }),
    ];
    this.gateSign = new THREE.MeshBasicMaterial({ map: makeTextTexture("DUCK!", "#d56a20", "#fff4e2"), toneMapped: false, transparent: true, side: THREE.DoubleSide });
  }

  reset() {
    for (const obstacle of this.obstacles) this.scene.remove(obstacle.group);
    for (const coin of this.coins) this.scene.remove(coin.group);
    for (const powerup of this.powerups) this.scene.remove(powerup.group);
    this.obstacles.length = 0;
    this.coins.length = 0;
    this.powerups.length = 0;
    this.bonus = 0;
    this.coinsCollected = 0;
    this.coinStreak = 0;
    this.lastCoinAt = -10;
    this.magnetTimer = 0;
    this.powerupMileage = 260;
  }

  createTrain(lane, z, variant = 0) {
    const group = new THREE.Group();
    const bodyMat = shared.trainBase[variant % shared.trainBase.length];
    const accentMat = shared.trainAccent[variant % shared.trainAccent.length];
    const cars = Math.random() > 0.52 ? 2 : 1;
    const carDepth = 5.8;
    const gap = 0.26;
    const totalDepth = cars * carDepth + (cars - 1) * gap;
    const front = totalDepth / 2;

    for (let c = 0; c < cars; c++) {
      const car = new THREE.Group();
      car.position.z = front - carDepth / 2 - c * (carDepth + gap);
      const body = new THREE.Mesh(trainBodyGeometry, bodyMat);
      body.position.y = 1.46;
      body.castShadow = true;
      car.add(body);

      const roof = new THREE.Mesh(new RoundedBoxGeometry(1.9, 0.2, 5.35, 3, 0.06), shared.chrome);
      roof.position.y = 2.77;
      roof.castShadow = true;
      car.add(roof);

      const under = new THREE.Mesh(new THREE.BoxGeometry(1.72, 0.38, 4.5), shared.undercarriage);
      under.position.y = 0.38;
      car.add(under);

      const stripe = new THREE.Mesh(new THREE.BoxGeometry(2.105, 0.22, 4.9), accentMat);
      stripe.position.y = 1.08;
      car.add(stripe);

      const skirt = new THREE.Mesh(new THREE.BoxGeometry(2.0, 0.25, 4.45), shared.dark);
      skirt.position.y = 0.55;
      car.add(skirt);

      for (const side of [-1, 1]) {
        for (let i = 0; i < 4; i++) {
          const window = new THREE.Mesh(windowGeometry, shared.glass);
          window.position.set(side * 1.045, 1.92, 1.92 - i * 1.24);
          car.add(window);
        }
        const lightStrip = new THREE.Mesh(
          new THREE.BoxGeometry(0.03, 0.075, 4.6),
          new THREE.MeshStandardMaterial({ color: 0xffd8a4, emissive: 0xffb45d, emissiveIntensity: 2.2 }),
        );
        lightStrip.position.set(side * 1.05, 0.93, 0);
        car.add(lightStrip);

        const bogie = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.36, 1.15), shared.undercarriage);
        bogie.position.set(side * 0.82, 0.28, c === 0 ? 1.6 : -1.5);
        car.add(bogie);
        for (const wheelSide of [-1, 1]) {
          const wheel = new THREE.Mesh(new THREE.CylinderGeometry(0.19, 0.19, 0.1, 12), shared.wheel);
          wheel.rotation.z = Math.PI / 2;
          wheel.position.set(side * (0.94 + wheelSide * 0.07), 0.2, c === 0 ? 1.6 : -1.5);
          car.add(wheel);
        }
      }

      const roofVent = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.15, 1.7), shared.undercarriage);
      roofVent.position.set(0, 2.89, 0.4);
      car.add(roofVent);

      group.add(car);
    }

    // Front fascia.
    const frontZ = front + 0.02;
    const windshield = new THREE.Mesh(new THREE.BoxGeometry(1.48, 0.74, 0.05), shared.glass);
    windshield.position.set(0, 2.08, frontZ);
    group.add(windshield);
    const windshieldTop = new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.1, 0.08), shared.chrome);
    windshieldTop.position.set(0, 2.48, frontZ);
    group.add(windshieldTop);

    const sign = new THREE.Mesh(new THREE.PlaneGeometry(1.2, 0.45), this.trainSigns[variant % this.trainSigns.length]);
    sign.position.set(0, 2.68, frontZ + 0.03);
    group.add(sign);

    const bumper = new THREE.Mesh(trainBumperGeometry, shared.dark);
    bumper.position.set(0, 0.66, frontZ + 0.02);
    group.add(bumper);

    for (const side of [-1, 1]) {
      const headlight = new THREE.Mesh(new THREE.CircleGeometry(0.12, 12), shared.warmLight);
      headlight.position.set(side * 0.7, 1.14, frontZ + 0.04);
      group.add(headlight);
      const glow = new THREE.Sprite(
        new THREE.SpriteMaterial({
          map: shared.glow,
          color: 0xffc36a,
          transparent: true,
          opacity: 0.45,
          depthWrite: false,
          blending: THREE.AdditiveBlending,
        }),
      );
      glow.position.set(side * 0.7, 1.14, frontZ + 0.12);
      glow.scale.setScalar(0.8);
      group.add(glow);
    }

    const frontNumber = new THREE.Mesh(
      new THREE.PlaneGeometry(0.34, 0.34),
      new THREE.MeshBasicMaterial({ map: makeTextTexture(cars === 2 ? "M2" : "M1", "#1a2a3c", "#ffc53d"), toneMapped: false }),
    );
    frontNumber.position.set(0.72, 0.71, frontZ + 0.09);
    group.add(frontNumber);

    group.position.set(LANE_X[lane], 0, z - totalDepth / 2);
    group.userData.train = true;
    this.scene.add(group);
    this.obstacles.push({
      group,
      type: "train",
      lane,
      x: LANE_X[lane],
      halfWidth: 1.07,
      halfDepth: totalDepth / 2,
      height: 2.9,
    });
    this.spawnObstacleGlow(group, LANE_X[lane], 0.85, z - totalDepth * 0.4, 0xffc069);
  }

  spawnObstacleGlow(group, x, y, z, color) {
    const sprite = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: shared.glow,
        color,
        transparent: true,
        opacity: 0.12,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      }),
    );
    sprite.position.set(x - group.position.x, y, z - group.position.z);
    sprite.scale.set(2.2, 2.2, 2.2);
    group.add(sprite);
  }

  createBarrier(lane, z, variant = 0) {
    const group = new THREE.Group();
    const panel = new THREE.Mesh(barrierPanelGeometry, new THREE.MeshStandardMaterial({ map: shared.hazard, roughness: 0.62 }));
    panel.position.y = 0.69;
    panel.castShadow = true;
    group.add(panel);

    const topRail = new THREE.Mesh(new THREE.BoxGeometry(2.12, 0.1, 0.2), shared.dark);
    topRail.position.y = 1.01;
    group.add(topRail);

    for (const side of [-1, 1]) {
      const leg = new THREE.Mesh(barrierLegGeometry, shared.verticalPost);
      leg.position.set(side * 0.76, 0.4, 0);
      leg.castShadow = true;
      group.add(leg);
      const foot = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.1, 0.62), shared.dark);
      foot.position.set(side * 0.76, 0.05, 0);
      group.add(foot);
      const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.09, 8, 6), shared.warningLight);
      lamp.position.set(side * 0.84, 1.1, 0.07);
      group.add(lamp);
    }

    const sign = new THREE.Mesh(
      new THREE.PlaneGeometry(0.72, 0.27),
      new THREE.MeshBasicMaterial({
        map: makeTextTexture(variant % 2 ? "NO ENTRY" : "STOP", "#253445", "#ffd05b"),
        toneMapped: false,
        side: THREE.DoubleSide,
      }),
    );
    sign.position.set(0, 0.71, 0.1);
    group.add(sign);

    group.position.set(LANE_X[lane], 0, z);
    group.userData.barrier = true;
    this.scene.add(group);
    this.obstacles.push({
      group,
      type: "barrier",
      lane,
      x: LANE_X[lane],
      halfWidth: 1.03,
      halfDepth: 0.48,
      height: 1.05,
    });
  }

  createGate(lane, z) {
    const group = new THREE.Group();
    for (const side of [-1, 1]) {
      const post = new THREE.Mesh(new THREE.BoxGeometry(0.22, 2.85, 0.24), shared.gatePost);
      post.position.set(side * 1.12, 1.42, 0);
      post.castShadow = true;
      group.add(post);
      const foot = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.16, 0.7), shared.dark);
      foot.position.set(side * 1.12, 0.08, 0);
      group.add(foot);
      const footLamp = new THREE.Mesh(new THREE.SphereGeometry(0.075, 7, 5), shared.warningLight);
      footLamp.position.set(side * 1.12, 2.64, 0.12);
      group.add(footLamp);
    }

    const header = new THREE.Mesh(new THREE.BoxGeometry(2.38, 0.48, 0.38), shared.gatePost);
    header.position.y = 2.12;
    header.castShadow = true;
    group.add(header);
    const sign = new THREE.Mesh(new THREE.PlaneGeometry(1.45, 0.54), this.gateSign);
    sign.position.set(0, 2.13, 0.21);
    group.add(sign);

    const beam = new THREE.Mesh(new THREE.BoxGeometry(2.18, 0.38, 0.26), new THREE.MeshStandardMaterial({ map: shared.hazard, roughness: 0.58 }));
    beam.position.y = 1.55;
    beam.castShadow = true;
    group.add(beam);
    const bottomPad = new THREE.Mesh(new THREE.BoxGeometry(2.06, 0.16, 0.3), shared.pad);
    bottomPad.position.y = 1.32;
    group.add(bottomPad);
    const strip = new THREE.Mesh(
      new THREE.BoxGeometry(1.6, 0.035, 0.11),
      new THREE.MeshStandardMaterial({ color: 0xffe0a0, emissive: 0xff9e34, emissiveIntensity: 2.7 }),
    );
    strip.position.set(0, 1.42, 0.15);
    group.add(strip);

    group.position.set(LANE_X[lane], 0, z);
    group.userData.gate = true;
    this.scene.add(group);
    this.obstacles.push({
      group,
      type: "gate",
      lane,
      x: LANE_X[lane],
      halfWidth: 1.16,
      halfDepth: 0.42,
      height: 2.4,
    });
  }

  spawnCoin(lane, z, y = 1.05) {
    const group = new THREE.Group();
    const disc = new THREE.Mesh(coinGeometry, shared.coin);
    group.add(disc);
    const rim = new THREE.Mesh(coinRimGeometry, shared.coinRim);
    rim.position.z = 0.025;
    group.add(rim);
    for (const side of [-1, 1]) {
      const core = new THREE.Mesh(coinCoreGeometry, shared.coinRim);
      core.position.set(0, 0, side * 0.032);
      group.add(core);
    }
    group.position.set(LANE_X[lane], y, z);
    group.scale.setScalar(0.9);
    group.userData.baseY = y;
    group.userData.phase = Math.random() * Math.PI * 2;
    this.scene.add(group);
    this.coins.push({ group, lane, x: LANE_X[lane], collected: false, magnetized: false });
  }

  spawnCoinLine(lane, z, count = 6, spacing = 2.2, arc = false) {
    for (let i = 0; i < count; i++) {
      const offset = (i - (count - 1) / 2) * spacing;
      const y = arc ? 1.02 + Math.sin((i / (count - 1)) * Math.PI) * 0.82 : 1.05;
      this.spawnCoin(lane, z + offset, y);
    }
  }

  spawnPowerup(lane, z) {
    const group = new THREE.Group();
    const orbMat = shared.magnet;
    const orb = new THREE.Mesh(new THREE.IcosahedronGeometry(0.26, 1), orbMat);
    group.add(orb);
    const shell = new THREE.Mesh(
      new THREE.IcosahedronGeometry(0.42, 1),
      new THREE.MeshBasicMaterial({ color: 0x8affdf, wireframe: true, transparent: true, opacity: 0.45, blending: THREE.AdditiveBlending, depthWrite: false }),
    );
    group.add(shell);
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(0.53, 0.025, 5, 32),
      new THREE.MeshBasicMaterial({ color: 0x9affea, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false }),
    );
    ring.rotation.x = Math.PI / 2;
    group.add(ring);
    const glow = new THREE.Sprite(
      new THREE.SpriteMaterial({ map: shared.glow, color: 0x61ffdd, transparent: true, opacity: 0.4, depthWrite: false, blending: THREE.AdditiveBlending }),
    );
    glow.scale.set(2.4, 2.4, 2.4);
    group.add(glow);
    group.position.set(LANE_X[lane], 1.15, z);
    group.userData.shell = shell;
    group.userData.ring = ring;
    this.scene.add(group);
    this.powerups.push({ group, lane, x: LANE_X[lane], collected: false, phase: Math.random() * 6 });
  }

  spawnPattern(z, difficulty = 0) {
    const lanes = [0, 1, 2];
    const shuffled = [...lanes].sort(() => Math.random() - 0.5);
    let blockedCount = 1;
    if (difficulty > 120 && Math.random() < 0.48) blockedCount = 2;
    if (difficulty > 420 && Math.random() < 0.17) blockedCount = 2;
    const blocked = shuffled.slice(0, blockedCount);
    const safe = shuffled.slice(blockedCount);
    const safeLane = safe[Math.floor(Math.random() * safe.length)];

    for (let i = 0; i < blocked.length; i++) {
      const lane = blocked[i];
      const roll = Math.random();
      if (roll < 0.44) this.createTrain(lane, z, Math.floor(Math.random() * 4));
      else if (roll < 0.76) this.createBarrier(lane, z, i);
      else this.createGate(lane, z);
    }

    if (difficulty > 35) {
      const coinCount = difficulty > 180 ? 8 : 6;
      const arc = Math.random() > 0.55;
      this.spawnCoinLine(safeLane, z + 1, coinCount, 2.15, arc);
    } else {
      this.spawnCoinLine(safeLane, z + 2, 4, 2.1, false);
    }

    if (difficulty > this.powerupMileage) {
      this.powerupMileage += 330;
      this.spawnPowerup(safeLane, z - 10);
    }
  }

  prefill() {
    this.spawnPattern(-52, 0);
    this.spawnPattern(-88, 30);
    this.spawnPattern(-124, 70);
    this.spawnPattern(-162, 110);
    this.spawnPattern(-200, 150);
    this.spawnPattern(-238, 190);
  }

  update(dt, speed, distance, magnetActive = false) {
    this.warningPhase += dt;
    shared.warningLight.emissiveIntensity = 1.8 + Math.sin(this.warningPhase * 8) * 1.5;
    const move = speed * dt;

    for (let i = this.obstacles.length - 1; i >= 0; i--) {
      const obstacle = this.obstacles[i];
      obstacle.group.position.z += move;
      if (obstacle.group.position.z > 26) {
        this.scene.remove(obstacle.group);
        this.obstacles.splice(i, 1);
      }
    }

    for (let i = this.coins.length - 1; i >= 0; i--) {
      const coin = this.coins[i];
      coin.group.position.z += move;
      coin.group.rotation.y += dt * 3.4;
      coin.group.position.y = coin.group.userData.baseY + Math.sin(this.warningPhase * 2.7 + coin.group.userData.phase) * 0.08;
      if (magnetActive) {
        const dx = -coin.group.position.x;
        const dz = -coin.group.position.z;
        const dist = Math.hypot(dx, dz);
        if (dist < 13) {
          coin.magnetized = true;
          const pull = 1 - Math.exp(-8 * dt);
          coin.group.position.x += dx * pull;
          coin.group.position.z += dz * pull;
          coin.group.position.y += (1.1 - coin.group.position.y) * pull;
        }
      }
      if (coin.group.position.z > 22) {
        this.scene.remove(coin.group);
        this.coins.splice(i, 1);
      }
    }

    for (let i = this.powerups.length - 1; i >= 0; i--) {
      const powerup = this.powerups[i];
      powerup.phase += dt;
      powerup.group.position.z += move;
      powerup.group.rotation.y += dt * 1.1;
      powerup.group.position.y = 1.15 + Math.sin(powerup.phase * 2) * 0.11;
      powerup.group.userData.ring.rotation.z += dt * 1.4;
      powerup.group.userData.shell.rotation.y -= dt * 0.8;
      if (powerup.group.position.z > 22) {
        this.scene.remove(powerup.group);
        this.powerups.splice(i, 1);
      }
    }

    this.goldBurst.update(dt);
    this.crashBurst.update(dt);
    this.sparkBurst.update(dt);
    if (this.lastCoinAt > 0) this.lastCoinAt -= dt;
    if (this.lastCoinAt <= 0) this.coinStreak = 0;
  }

  checkCollisions(player) {
    for (const obstacle of this.obstacles) {
      const dz = Math.abs(obstacle.group.position.z);
      if (dz > obstacle.halfDepth + 0.5) continue;
      if (Math.abs(player.x - obstacle.x) > obstacle.halfWidth + 0.28) continue;
      if (obstacle.type === "train") {
        if (player.y < obstacle.height - 0.12) return obstacle;
      } else if (obstacle.type === "barrier") {
        if (player.y < obstacle.height - 0.08) return obstacle;
      } else if (obstacle.type === "gate") {
        if (!player.sliding || player.y > 0.9) return obstacle;
      }
    }
    return null;
  }

  collectCoins(player, magnetActive = false) {
    let gained = 0;
    for (let i = this.coins.length - 1; i >= 0; i--) {
      const coin = this.coins[i];
      const closeZ = Math.abs(coin.group.position.z) < (coin.magnetized ? 2 : 1.15);
      const closeX = Math.abs(coin.group.position.x - player.x) < (coin.magnetized ? 1.6 : 0.95);
      const closeY = Math.abs(coin.group.position.y - (player.y + 1.02)) < 1.45;
      if (closeZ && closeX && closeY) {
        this.goldBurst.spawn(coin.group.position, 6, 1);
        this.scene.remove(coin.group);
        this.coins.splice(i, 1);
        gained += 1;
        this.coinsCollected += 1;
        this.coinStreak += 1;
        this.lastCoinAt = 1.2;
        this.bonus += 10;
        this.onCoin?.(this.coinStreak);
      }
    }
    return gained;
  }

  collectPowerups(player) {
    for (let i = this.powerups.length - 1; i >= 0; i--) {
      const powerup = this.powerups[i];
      if (Math.abs(powerup.group.position.z) < 1.2 && Math.abs(powerup.group.position.x - player.x) < 1.0) {
        this.sparkBurst.spawn(powerup.group.position, 20, 1.3);
        this.scene.remove(powerup.group);
        this.powerups.splice(i, 1);
        this.magnetTimer = 8;
        this.onPower?.();
        return true;
      }
    }
    return false;
  }

  crash(position) {
    this.crashBurst.spawn(position, 26, 1.5);
  }

  setMagnet(active) {
    this.magnetTimer = active ? Math.max(this.magnetTimer, 8) : 0;
  }
}

import * as THREE from "three";
import "./style.css";
import { Environment } from "./environment.js";
import { Player } from "./player.js";
import { Course } from "./obstacles.js";
import { SoundEngine } from "./audio.js";

const clamp = THREE.MathUtils.clamp;
const damp = THREE.MathUtils.damp;

const dom = {
  scene: document.querySelector("#scene"),
  hud: document.querySelector("#hud"),
  score: document.querySelector("#score"),
  distance: document.querySelector("#distance"),
  speedMult: document.querySelector("#speedMult"),
  speedFill: document.querySelector("#speedFill"),
  coinCount: document.querySelector("#coinCount"),
  bestScore: document.querySelector("#bestScore"),
  startBest: document.querySelector("#startBest"),
  laneMeter: document.querySelector("#laneMeter"),
  laneDots: [...document.querySelectorAll(".lane-dots i")],
  powerUp: document.querySelector("#powerUp"),
  powerTime: document.querySelector("#powerTime"),
  toast: document.querySelector("#toast"),
  startScreen: document.querySelector("#startScreen"),
  gameOverScreen: document.querySelector("#gameOverScreen"),
  pauseScreen: document.querySelector("#pauseScreen"),
  howScreen: document.querySelector("#howScreen"),
  playButton: document.querySelector("#playButton"),
  howButton: document.querySelector("#howButton"),
  howClose: document.querySelector("#howClose"),
  howPlay: document.querySelector("#howPlay"),
  retryButton: document.querySelector("#retryButton"),
  homeButton: document.querySelector("#homeButton"),
  resumeButton: document.querySelector("#resumeButton"),
  quitButton: document.querySelector("#quitButton"),
  pauseButton: document.querySelector("#pauseButton"),
  soundButton: document.querySelector("#soundButton"),
  finalScore: document.querySelector("#finalScore"),
  finalDistance: document.querySelector("#finalDistance"),
  finalCoins: document.querySelector("#finalCoins"),
  finalBest: document.querySelector("#finalBest"),
  newBest: document.querySelector("#newBest"),
  pauseScore: document.querySelector("#pauseScore"),
  pauseDistance: document.querySelector("#pauseDistance"),
  touchControls: document.querySelector("#touchControls"),
  fallback: document.querySelector("#webglFallback"),
};

const BEST_KEY = "metro-rush-best-v1";
const state = {
  mode: "menu",
  distance: 0,
  score: 0,
  speed: 18,
  best: Number.parseInt(localStorage.getItem(BEST_KEY) || "0", 10) || 0,
  coins: 0,
  magnet: 0,
  deadTimer: 0,
  elapsed: 0,
  spawnAt: 24,
  tutorialStep: 0,
  gameOverShown: false,
  trauma: 0,
  toastTimer: 0,
  scoreBumpTimer: 0,
  laneBump: 0,
};

let renderer;
try {
  renderer = new THREE.WebGLRenderer({
    canvas: dom.scene,
    antialias: true,
    powerPreference: "high-performance",
    alpha: false,
    stencil: false,
  });
} catch (error) {
  dom.fallback.hidden = false;
  throw error;
}

renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.setSize(window.innerWidth, window.innerHeight, false);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();
scene.background = new THREE.Color(0xdfa184);

const camera = new THREE.PerspectiveCamera(52, window.innerWidth / window.innerHeight, 0.1, 520);
camera.position.set(-4.7, 3.65, 8.9);
const cameraLook = new THREE.Vector3(0.25, 1.25, -5.2);
camera.lookAt(cameraLook);

const environment = new Environment(scene, renderer);
const player = new Player(scene);
const course = new Course(scene);
const sound = new SoundEngine();

const clock = new THREE.Clock();
let toastTimeout = 0;
let bumpedTimeout = 0;

function formatScore(value) {
  return Math.floor(Math.max(0, value)).toString().padStart(6, "0");
}

function refreshBest() {
  dom.bestScore.textContent = formatScore(state.best);
  dom.startBest.textContent = formatScore(state.best);
}

function showToast(message, duration = 1500) {
  dom.toast.textContent = message;
  dom.toast.classList.add("show");
  window.clearTimeout(toastTimeout);
  toastTimeout = window.setTimeout(() => dom.toast.classList.remove("show"), duration);
}

function flashScore() {
  dom.score.classList.add("bump");
  window.clearTimeout(bumpedTimeout);
  bumpedTimeout = window.setTimeout(() => dom.score.classList.remove("bump"), 180);
}

function updateHud(force = false) {
  const score = Math.floor(state.score);
  if (force || dom.score.textContent !== formatScore(score)) {
    dom.score.textContent = formatScore(score);
  }
  if (force || dom.distance.textContent !== String(Math.floor(state.distance))) {
    dom.distance.textContent = String(Math.floor(state.distance));
  }
  if (force || dom.coinCount.textContent !== String(state.coins)) {
    dom.coinCount.textContent = String(state.coins);
  }
  const speedNorm = clamp((state.speed - 18) / 20, 0, 1);
  dom.speedMult.textContent = `x${(1 + speedNorm * 1.1).toFixed(1)}`;
  dom.speedFill.style.width = `${Math.round(8 + speedNorm * 92)}%`;
  dom.bestScore.textContent = formatScore(Math.max(state.best, score));
  for (let i = 0; i < dom.laneDots.length; i++) {
    dom.laneDots[i].classList.toggle("active", i === player.targetLane);
  }
  const magnetOn = state.magnet > 0;
  dom.powerUp.hidden = !magnetOn;
  if (magnetOn) {
    dom.powerTime.textContent = `${Math.ceil(state.magnet)}s`;
  }
}

function setMutedUi(muted) {
  dom.soundButton.classList.toggle("muted", muted);
  dom.soundButton.setAttribute("aria-label", muted ? "Unmute sound" : "Mute sound");
  dom.soundButton.title = muted ? "Unmute sound" : "Mute sound";
}

function startGame() {
  sound.init();
  sound.startMusic();
  sound.click();
  state.mode = "playing";
  state.distance = 0;
  state.score = 0;
  state.speed = 18;
  state.coins = 0;
  state.magnet = 0;
  state.deadTimer = 0;
  state.elapsed = 0;
  state.spawnAt = 24;
  state.tutorialStep = 0;
  state.gameOverShown = false;
  state.trauma = 0;
  state.laneBump = 0;
  course.reset();
  course.prefill();
  course.magnetTimer = 0;
  player.reset();
  updateHud(true);

  dom.startScreen.classList.add("is-leaving");
  window.setTimeout(() => {
    if (state.mode !== "menu") dom.startScreen.hidden = true;
  }, 460);
  dom.gameOverScreen.hidden = true;
  dom.pauseScreen.hidden = true;
  dom.howScreen.hidden = true;
  dom.hud.hidden = false;
  dom.laneMeter.hidden = false;
  dom.touchControls.hidden = false;
  dom.toast.classList.remove("show");
  showToast("RUN!", 850);
  window.setTimeout(() => {
    if (state.mode === "playing" && state.tutorialStep === 0) {
      showToast("←  →  SWITCH LANES", 1700);
      state.tutorialStep = 1;
    }
  }, 950);
}

function goHome() {
  sound.stopMusic();
  state.mode = "menu";
  state.distance = 0;
  state.score = 0;
  state.speed = 18;
  state.coins = 0;
  state.magnet = 0;
  course.reset();
  player.reset();
  camera.position.set(-4.7, 3.65, 8.9);
  cameraLook.set(0.25, 1.25, -5.2);
  dom.startScreen.hidden = false;
  dom.startScreen.classList.remove("is-leaving");
  dom.gameOverScreen.hidden = true;
  dom.pauseScreen.hidden = true;
  dom.howScreen.hidden = true;
  dom.hud.hidden = true;
  dom.laneMeter.hidden = true;
  dom.touchControls.hidden = true;
  dom.powerUp.hidden = true;
  dom.toast.classList.remove("show");
  refreshBest();
}

function pauseGame() {
  if (state.mode !== "playing") return;
  state.mode = "paused";
  dom.pauseScreen.hidden = false;
  dom.touchControls.hidden = true;
  dom.pauseScore.textContent = formatScore(state.score);
  dom.pauseDistance.textContent = `${Math.floor(state.distance)}m`;
  dom.toast.classList.remove("show");
  sound.stopMusic();
  sound.click();
}

function resumeGame() {
  if (state.mode !== "paused") return;
  state.mode = "playing";
  dom.pauseScreen.hidden = true;
  dom.touchControls.hidden = false;
  sound.startMusic();
  sound.click();
  clock.getDelta();
}

function endRun() {
  if (state.gameOverShown) return;
  state.gameOverShown = true;
  state.mode = "over";
  const finalScore = Math.floor(state.score);
  const isNewBest = finalScore > state.best;
  if (isNewBest) {
    state.best = finalScore;
    localStorage.setItem(BEST_KEY, String(state.best));
  }
  refreshBest();
  dom.finalScore.textContent = formatScore(finalScore);
  dom.finalDistance.textContent = `${Math.floor(state.distance)}m`;
  dom.finalCoins.textContent = String(state.coins);
  dom.finalBest.textContent = formatScore(state.best);
  dom.newBest.hidden = !isNewBest;
  dom.gameOverScreen.hidden = false;
  dom.touchControls.hidden = true;
  dom.gameOverScreen.querySelector(".modal-card").animate(
    [
      { transform: "translateY(22px) scale(.97)", opacity: 0 },
      { transform: "translateY(0) scale(1)", opacity: 1 },
    ],
    { duration: 380, easing: "cubic-bezier(.18,1.25,.3,1)" },
  );
}

function crash(obstacle) {
  if (state.mode !== "playing") return;
  state.mode = "dead";
  state.deadTimer = 0;
  state.trauma = 1;
  player.die();
  sound.crash();
  sound.stopMusic();
  course.crash(new THREE.Vector3(player.x, 1.1 + player.y, 0));
  dom.toast.classList.remove("show");
  dom.touchControls.hidden = true;
  document.body.classList.add("impact");
  window.setTimeout(() => document.body.classList.remove("impact"), 240);
  if (navigator.vibrate) navigator.vibrate([35, 35, 65]);
  state.lastObstacle = obstacle;
}

function laneLeft() {
  if (state.mode !== "playing") return;
  if (player.moveLeft()) {
    sound.swipe(-1);
    state.laneBump = 1;
  }
}

function laneRight() {
  if (state.mode !== "playing") return;
  if (player.moveRight()) {
    sound.swipe(1);
    state.laneBump = 1;
  }
}

function doJump() {
  if (state.mode !== "playing") return;
  if (player.jump()) sound.jump();
}

function doSlide() {
  if (state.mode !== "playing") return;
  if (player.slide()) sound.slide();
}

function handleSpawn(dt) {
  if (state.distance >= state.spawnAt) {
    course.spawnPattern(-270, state.distance);
    const gap = 29 + Math.min(13, state.speed * 0.28) + Math.random() * 5;
    state.spawnAt += gap;
  }
  // Keep the queue fed if a frame stalls.
  let safety = 0;
  while (state.distance > state.spawnAt && safety++ < 3) {
    course.spawnPattern(-270, state.distance);
    state.spawnAt += 33;
  }
}

function updateGame(dt) {
  state.elapsed += dt;
  state.speed = 18 + Math.min(state.distance * 0.026, 20);
  state.distance += state.speed * dt;
  state.score = state.distance * 10 + state.coins * 50;

  if (state.magnet > 0) {
    state.magnet = Math.max(0, state.magnet - dt);
    course.magnetTimer = state.magnet;
  }

  const magnetActive = state.magnet > 0;
  handleSpawn(dt);
  environment.update(dt, state.speed, state.distance);
  player.update(dt, state.speed);
  course.update(dt, state.speed, state.distance, magnetActive);
  const gained = course.collectCoins(player, magnetActive);
  if (gained > 0) {
    state.coins += gained;
    state.score = state.distance * 10 + state.coins * 50;
    flashScore();
  }
  if (course.collectPowerups(player)) {
    state.magnet = 8;
    sound.power();
    showToast("COIN MAGNET · 8 SECONDS", 1800);
  }

  const hit = course.checkCollisions(player);
  if (hit) crash(hit);

  if (state.distance > 55 && state.tutorialStep === 1) {
    state.tutorialStep = 2;
    showToast("JUMP THE LOW BARRIERS", 1600);
  } else if (state.distance > 150 && state.tutorialStep === 2) {
    state.tutorialStep = 3;
    showToast("ROLL UNDER THE SIGNS", 1600);
  }

  updateHud();
}

function updateDead(dt) {
  state.deadTimer += dt;
  state.speed = damp(state.speed, 0, 2.8, dt);
  state.trauma = Math.max(0, state.trauma - dt * 1.8);
  environment.update(dt, state.speed, state.distance);
  course.update(dt, state.speed, state.distance, false);
  player.update(dt, state.speed);
  updateHud();
  if (state.deadTimer > 0.9 && !state.gameOverShown) endRun();
}

function updateMenu(dt) {
  state.elapsed += dt;
  const menuSpeed = 5.6;
  environment.update(dt, menuSpeed, state.elapsed * 2);
  player.update(dt, menuSpeed, { menu: true });
  state.trauma = Math.max(0, state.trauma - dt * 2);
  if (state.laneBump > 0) state.laneBump = Math.max(0, state.laneBump - dt * 3);
}

function updateCamera(dt) {
  const inChase = state.mode !== "menu";
  if (inChase) {
    const speedNorm = clamp((state.speed - 18) / 20, 0, 1);
    const slideDip = player.sliding ? 0.3 : 0;
    const targetX = player.x * 0.44;
    const targetY = 4.15 + player.y * 0.11 - slideDip + Math.sin(state.elapsed * 1.35) * 0.018;
    const targetZ = 7.85 + speedNorm * 0.55;
    const lambda = state.mode === "dead" ? 2.4 : 3.8;
    camera.position.x = damp(camera.position.x, targetX, lambda, dt);
    camera.position.y = damp(camera.position.y, targetY, lambda, dt);
    camera.position.z = damp(camera.position.z, targetZ, lambda, dt);
    const lookX = player.x * 0.26;
    const lookY = 1.25 + player.y * 0.18 - slideDip * 0.14;
    const lookZ = -8.8 - speedNorm * 2.2;
    cameraLook.x = damp(cameraLook.x, lookX, 4, dt);
    cameraLook.y = damp(cameraLook.y, lookY, 4, dt);
    cameraLook.z = damp(cameraLook.z, lookZ, 3, dt);
    const targetFov = 56 + speedNorm * 9;
    camera.fov = damp(camera.fov, targetFov, 3, dt);
  } else {
    const t = state.elapsed;
    const targetX = -4.7 + Math.sin(t * 0.22) * 0.22;
    const targetY = 3.65 + Math.sin(t * 0.35) * 0.06;
    const targetZ = 8.9 + Math.sin(t * 0.18) * 0.12;
    camera.position.x = damp(camera.position.x, targetX, 1.7, dt);
    camera.position.y = damp(camera.position.y, targetY, 1.7, dt);
    camera.position.z = damp(camera.position.z, targetZ, 1.7, dt);
    cameraLook.x = damp(cameraLook.x, 0.25, 2, dt);
    cameraLook.y = damp(cameraLook.y, 1.25, 2, dt);
    cameraLook.z = damp(cameraLook.z, -5.2, 2, dt);
    camera.fov = damp(camera.fov, 50, 2, dt);
  }

  if (state.trauma > 0) {
    const shake = state.trauma * state.trauma;
    camera.position.x += (Math.random() - 0.5) * shake * 0.8;
    camera.position.y += (Math.random() - 0.5) * shake * 0.55;
    cameraLook.x += (Math.random() - 0.5) * shake * 0.25;
    cameraLook.y += (Math.random() - 0.5) * shake * 0.25;
  }

  camera.lookAt(cameraLook);
  camera.updateProjectionMatrix();
}

function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);

  if (state.mode === "menu") updateMenu(dt);
  else if (state.mode === "playing") updateGame(dt);
  else if (state.mode === "dead") updateDead(dt);
  else if (state.mode === "over") {
    state.trauma = Math.max(0, state.trauma - dt * 2);
    const speed = damp(state.speed, 0, 4, dt);
    state.speed = speed;
    environment.update(dt, speed, state.distance);
    course.update(dt, speed, state.distance, false);
    player.update(dt, speed);
  }

  updateCamera(dt);
  renderer.render(scene, camera);
}

function handleKeyDown(event) {
  const key = event.key;
  if (["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", " ", "Spacebar"].includes(key)) {
    event.preventDefault();
  }
  if (event.repeat) return;

  if (state.mode === "menu") {
    if (key === "Enter" || key === " " || key === "Spacebar") startGame();
    return;
  }
  if (state.mode === "paused") {
    if (key === "Escape" || key === "p" || key === "P") resumeGame();
    return;
  }
  if (state.mode === "over") {
    if (key === "Enter" || key === "r" || key === "R") startGame();
    return;
  }
  if (state.mode !== "playing") return;

  switch (key) {
    case "ArrowLeft":
    case "a":
    case "A":
      laneLeft();
      break;
    case "ArrowRight":
    case "d":
    case "D":
      laneRight();
      break;
    case "ArrowUp":
    case "w":
    case "W":
    case " ":
    case "Spacebar":
      doJump();
      break;
    case "ArrowDown":
    case "s":
    case "S":
      doSlide();
      break;
    case "Escape":
    case "p":
    case "P":
      pauseGame();
      break;
    default:
      break;
  }
}

let pointerStart = null;
function onPointerDown(event) {
  if (state.mode !== "playing") return;
  pointerStart = { x: event.clientX, y: event.clientY, time: performance.now(), id: event.pointerId };
  dom.scene.setPointerCapture?.(event.pointerId);
}

function onPointerUp(event) {
  if (!pointerStart || state.mode !== "playing") {
    pointerStart = null;
    return;
  }
  const dx = event.clientX - pointerStart.x;
  const dy = event.clientY - pointerStart.y;
  const elapsed = performance.now() - pointerStart.time;
  const distance = Math.hypot(dx, dy);
  pointerStart = null;

  if (distance < 16 && elapsed < 420) {
    doJump();
    return;
  }
  if (distance < 24) return;

  if (Math.abs(dx) > Math.abs(dy)) {
    if (dx < 0) laneLeft();
    else laneRight();
  } else if (dy < 0) {
    doJump();
  } else {
    doSlide();
  }
}

function bindTouchButtons() {
  for (const button of dom.touchControls.querySelectorAll("[data-action]")) {
    button.addEventListener("pointerdown", (event) => {
      event.preventDefault();
      event.stopPropagation();
      button.classList.add("pressed");
      window.setTimeout(() => button.classList.remove("pressed"), 120);
      const action = button.dataset.action;
      if (action === "left") laneLeft();
      else if (action === "right") laneRight();
      else if (action === "jump") doJump();
      else if (action === "slide") doSlide();
    });
  }
}

dom.playButton.addEventListener("click", startGame);
dom.howButton.addEventListener("click", () => {
  sound.init();
  sound.click();
  dom.howScreen.hidden = false;
});
dom.howClose.addEventListener("click", () => {
  sound.click();
  dom.howScreen.hidden = true;
});
dom.howPlay.addEventListener("click", () => {
  dom.howScreen.hidden = true;
  startGame();
});
dom.retryButton.addEventListener("click", () => {
  dom.gameOverScreen.hidden = true;
  startGame();
});
dom.homeButton.addEventListener("click", goHome);
dom.resumeButton.addEventListener("click", resumeGame);
dom.pauseButton.addEventListener("click", pauseGame);
dom.quitButton.addEventListener("click", goHome);
dom.soundButton.addEventListener("click", () => {
  sound.init();
  const muted = sound.toggleMuted();
  setMutedUi(muted);
  if (!muted) sound.click();
});
dom.scene.addEventListener("pointerdown", onPointerDown);
dom.scene.addEventListener("pointerup", onPointerUp);
dom.scene.addEventListener("pointercancel", () => (pointerStart = null));
window.addEventListener("keydown", handleKeyDown);
window.addEventListener("blur", () => {
  if (state.mode === "playing") pauseGame();
});
document.addEventListener("visibilitychange", () => {
  if (document.hidden && state.mode === "playing") pauseGame();
});

window.addEventListener("resize", () => {
  const width = window.innerWidth;
  const height = window.innerHeight;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(width, height, false);
  camera.aspect = width / height;
  camera.updateProjectionMatrix();
});

course.onCoin = (streak) => {
  sound.coin(streak);
  flashScore();
};
course.onPower = () => {};

bindTouchButtons();
refreshBest();
setMutedUi(false);
updateHud(true);
animate();

