import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });

const errors = [];
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(1200);
const menuInfo = await page.evaluate(() => {
  const g = window.__metro;
  return { mode: g.state.mode, calls: g.renderer.info.render.calls, tris: g.renderer.info.render.triangles, software: g.softwareRenderer, gpu: g.gpuName };
});
console.log('menu', menuInfo);
await page.screenshot({ path: 'screenshots/menu3.png', timeout: 60000 });

await page.locator('#playButton').click();
await page.waitForTimeout(900);
const afterStart = await page.evaluate(() => ({ mode: window.__metro.state.mode, y: window.__metro.player.y, lane: window.__metro.player.targetLane }));
console.log('started', afterStart);

await page.keyboard.press('ArrowLeft');
await page.waitForTimeout(260);
const left = await page.evaluate(() => ({ lane: window.__metro.player.targetLane, x: +window.__metro.player.x.toFixed(2) }));
await page.keyboard.press('ArrowRight');
await page.waitForTimeout(260);
const right = await page.evaluate(() => ({ lane: window.__metro.player.targetLane, x: +window.__metro.player.x.toFixed(2) }));
await page.keyboard.press('ArrowUp');
await page.waitForTimeout(220);
const jumped = await page.evaluate(() => ({ y: +window.__metro.player.y.toFixed(2), grounded: window.__metro.player.grounded }));
await page.waitForTimeout(900);
await page.keyboard.press('ArrowDown');
await page.waitForTimeout(140);
const slid = await page.evaluate(() => ({ sliding: window.__metro.player.sliding, y: +window.__metro.player.y.toFixed(2) }));
console.log('controls', { left, right, jumped, slid });

await page.waitForTimeout(1700);
const live = await page.evaluate(() => {
  const g = window.__metro;
  return { mode: g.state.mode, distance: +g.state.distance.toFixed(1), score: Math.floor(g.state.score), coins: g.state.coins, calls: g.renderer.info.render.calls, tris: g.renderer.info.render.triangles };
});
console.log('live', live);
await page.screenshot({ path: 'screenshots/game3.png', timeout: 60000 });

// Pause / resume.
await page.locator('#pauseButton').click();
await page.waitForTimeout(350);
const paused = await page.evaluate(() => ({ mode: window.__metro.state.mode, shown: !document.querySelector('#pauseScreen').hidden }));
await page.locator('#resumeButton').click();
await page.waitForTimeout(350);
const resumed = await page.evaluate(() => ({ mode: window.__metro.state.mode, hidden: document.querySelector('#pauseScreen').hidden }));
console.log('pause', { paused, resumed });

// Let the run end naturally.
await page.waitForTimeout(6500);
const end = await page.evaluate(() => ({ mode: window.__metro.state.mode, shown: !document.querySelector('#gameOverScreen').hidden, final: window.__metro.state.score }));
console.log('end', end);
await page.screenshot({ path: 'screenshots/gameover3.png', timeout: 60000 });

// Mobile layout and touch controls.
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
mobile.on('console', m => { if (m.type() === 'error') errors.push('mobile console: ' + m.text()); });
mobile.on('pageerror', e => errors.push('mobile pageerror: ' + e.message));
await mobile.goto('http://localhost:3002', { waitUntil: 'load' });
await mobile.waitForTimeout(1200);
await mobile.screenshot({ path: 'screenshots/mobile-menu3.png', timeout: 60000 });
await mobile.locator('#playButton').click();
await mobile.waitForTimeout(900);
const mobileHud = await mobile.evaluate(() => {
  const g = window.__metro;
  const tc = document.querySelector('#touchControls');
  const r = tc.getBoundingClientRect();
  return { mode: g.state.mode, display: getComputedStyle(tc).display, rect: { x: r.x, y: r.y, w: r.width, h: r.height }, vw: innerWidth, vh: innerHeight, safeBottom: getComputedStyle(document.documentElement).getPropertyValue('--safe-bottom') };
});
console.log('mobile hud', mobileHud);
await mobile.locator('[data-action="left"]').tap();
await mobile.waitForTimeout(300);
const mobileLeft = await mobile.evaluate(() => ({ lane: window.__metro.player.targetLane, x: +window.__metro.player.x.toFixed(2) }));
await mobile.locator('[data-action="right"]').tap();
await mobile.waitForTimeout(300);
await mobile.locator('[data-action="jump"]').tap();
await mobile.waitForTimeout(220);
