await page.screenshot({ path: 'screenshots/final-menu.png', timeout: 60000 });
await page.locator('#playButton').click();
await page.waitForTimeout(2800);
const desktop = await page.evaluate(() => {
  const g = window.__metro;
  return { mode: g.state.mode, distance: +g.state.distance.toFixed(1), score: Math.floor(g.state.score), coins: g.state.coins, calls: g.renderer.info.render.calls, tris: g.renderer.info.render.triangles, software: g.softwareRenderer };
});
await page.screenshot({ path: 'screenshots/final-game.png', timeout: 60000 });
console.log('desktop', desktop);

const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
