await mobile.waitForTimeout(900);
await mobile.locator('[data-action="left"]').tap();
await mobile.waitForTimeout(450);
await mobile.screenshot({ path: 'screenshots/final-mobile-game.png', timeout: 60000 });
const mobileState = await mobile.evaluate(() => {
  const g = window.__metro;
  const tc = document.querySelector('#touchControls').getBoundingClientRect();
  return { mode: g.state.mode, lane: g.player.targetLane, distance: +g.state.distance.toFixed(1), touchVisible: !document.querySelector('#touchControls').hidden, touchBottom: Math.round(innerHeight - tc.bottom) };
});
console.log('mobile', mobileState);
console.log('errors', errors);
await browser.close();

